window.__SCIENCE_INITIAL_DATA__ = {"issue": "2026-W47", "weekStart": "2026-11-16", "weekEnd": "2026-11-22", "generatedAt": "2026-11-25", "mode": "metadata", "editorialNote": "自动抓取自 Europe PMC 的可溯源数据；主题期刊范围使用2025年中科院最后一版大类分区候选池，摘要AI初稿需人工审校；历史周刊默认不覆盖。", "rankPolicy": {"scheme": "CAS", "edition": 2025, "basis": "large_category"}, "topicBackfillComplete": true, "errors": [], "papers": [{"id": "doi-10-1038-s41467-026-79485-7", "journal": "Nature Communications", "group": "SingleCell", "sections": ["SingleCell"], "date": "2026-11-22", "type": "Research Article", "title": "Heparan sulfate sulfatases are essential for the patterning of human stem cell-derived midbrain dopaminergic neurons.", "zh": "", "authors": "Tremolanti C, Abaurre C, Chien YC, Gamon LF, Mitchell CW, Gout E, Agirre E, Lyu G, Karlsson R, Davies MJ, Castelo-Branco G, Vivès RR, Saltó C, Marklund U, Miller RL, Turnbull JE, Arenas E.", "doi": "10.1038/s41467-026-79485-7", "pmid": "43069341", "url": "https://doi.org/10.1038/s41467-026-79485-7", "tags": [], "abstract": "Midbrain dopaminergic neurons (mDA) are selectively lost in Parkinson's disease, driving sustained efforts to generate bona fide mDA neurons from human-induced pluripotent stem cells (iPSCs) for replacement therapy. While morphogen gradients and transcription factors have been extensively studied, extracellular regulators remain largely overlooked. Here, we identify the heparan sulfate-modifying enzymes SULF1 and SULF2 as essential for establishing mDA neuron identity in vitro. Using CRISPR/Cas9-engineered iPSCs, we show that loss of SULF1/2 increases 6-O-sulfated heparan sulfate species and disrupts patterning both at the anteroposterior and dorsoventral axes in human iPSC-derived mDA cultures. Double-knockout cells thus fail to acquire ventral midbrain fates and instead adopt hindbrain, spinal cord and neural crest-like identities as revealed by single-nucleus RNA sequencing. Mechanistically, we partially explain the changed patterning to aberrant FGF signaling and demonstrate that FGF inhibition redirects cells toward midbrain fates, however without restoring ventral identity. These findings establish a critical role for SULF1/2 in mDA neuron in vitro differentiation and uncover a previously unrecognized layer of extracellular control over neural patterning.", "rankSystem": "CAS", "rankEdition": 2025, "rankZone": 1, "finding": "", "why": "", "problem": "", "innovation": "", "limitations": "", "next": "", "reviewStatus": "metadata_only", "featured": true}, {"id": "doi-10-1016-j-ajo-2026-11-013", "journal": "American Journal of Ophthalmology", "group": "Eye", "sections": ["Eye"], "date": "2026-11-21", "type": "Research Article", "title": "Retinal Structure Reflects Cumulative Blast Exposure and Blast-Related Mild Traumatic Brain Injury.", "zh": "", "authors": "Gustafson JA, Walter K, Parenteau C, Hao S, Fortier CB, Milberg WP, Fortenbaugh FC.", "doi": "10.1016/j.ajo.2026.11.013", "pmid": "43067492", "url": "https://doi.org/10.1016/j.ajo.2026.11.013", "tags": [], "abstract": "Objective U.S. military service members experienced a high rate of blast exposures during post-9/11 military conflicts. Though a growing body of literature suggests that these exposures have long term consequences for health, objective biomarkers of blast-related neurotrauma remain limited. We used optical coherence tomography (OCT) to determine whether blast-related mild traumatic brain injury (mTBI) and cumulative blast exposure burden were associated with retinal microstructural changes. Design A retrospective, cross-sectional cohort study at VA Boston Healthcare System. Participants Seventy-three United States post 9/11 veterans enrolled in the Translational Research Center for TBI & Stress Disorders (TRACTS) longitudinal cohort study who underwent OCT imaging based on assessment availability. Methods Principal observations were blast-related mild traumatic brain injury and cumulative lifetime blast exposure burden. Main outcomes measures Retinal thickness as measured by high-resolution Spectralis OCT imaging, including 7 individual macular layers, combined macular layers (inner retina, outer retina, and total retina), and the peripapillary retinal nerve fiber layer, using automated segmentation software. Results Among 73 participants (mean [SD] age, 40.8 [9.4] years; 63 [86%] male), 25 had a history of blast mTBI (blast mTBI+) and 48 did not (blast mTBI-). Participants with blast mTBI+ had significantly thicker retinal layers in the macula, specifically in the 3mm quadrants around the fovea. The peripapillary RNFL (pRNFL) was significantly thinner in the blast mTBI+ group (p = .009), with the most significant thinning occurring nasally, most notably superior/nasal (p Conclusions Retinal structural measures distinguished veterans with blast-related mild traumatic brain injury and predicted cumulative blast exposure burden. These findings support OCT as an accessible approach for identifying retinal biomarkers of blast-related neurotrauma and cumulative blast exposure.", "rankSystem": "CAS", "rankEdition": 2025, "rankZone": 1, "finding": "", "why": "", "problem": "", "innovation": "", "limitations": "", "next": "", "reviewStatus": "metadata_only"}, {"id": "doi-10-1016-j-ophtha-2026-10-021", "journal": "Ophthalmology", "group": "Eye", "sections": ["Eye"], "date": "2026-11-20", "type": "Letter", "title": "Re: Montesano et al.: Longitudinal Visual Field and Quality-of-Life Change in the Treatment for Advanced Glaucoma Study (Ophthalmology. 2026;133:996-1005).", "zh": "", "authors": "Gao J, Wang Z, Zhou Y.", "doi": "10.1016/j.ophtha.2026.10.021", "pmid": "43062383", "url": "https://doi.org/10.1016/j.ophtha.2026.10.021", "tags": [], "abstract": "", "rankSystem": "CAS", "rankEdition": 2025, "rankZone": 1, "finding": "", "why": "", "problem": "", "innovation": "", "limitations": "", "next": "", "reviewStatus": "metadata_only"}, {"id": "doi-10-1016-j-ophtha-2026-10-026", "journal": "Ophthalmology", "group": "Eye", "sections": ["Eye"], "date": "2026-11-20", "type": "Letter", "title": "Authors' Reply: Impact of Intravitreal Anti-VEGF Injections on Cataract Development.", "zh": "", "authors": "Choi J, Choi E, Kang SW, Kim SJ, Hwang S, Lee H.", "doi": "10.1016/j.ophtha.2026.10.026", "pmid": "43066665", "url": "https://doi.org/10.1016/j.ophtha.2026.10.026", "tags": [], "abstract": "", "rankSystem": "CAS", "rankEdition": 2025, "rankZone": 1, "finding": "", "why": "", "problem": "", "innovation": "", "limitations": "", "next": "", "reviewStatus": "metadata_only"}, {"id": "doi-10-1016-j-ophtha-2026-10-024", "journal": "Ophthalmology", "group": "Eye", "sections": ["Eye"], "date": "2026-11-20", "type": "Letter", "title": "Reply.", "zh": "", "authors": "Liu S, Szabo A, Zarouchlioti C, Bhattacharyya N, Nguyen Q, Costa MA, Luben RN, Dudakova L, Skalicka P, Horak M, Khawaja AP, Pontikos N, Muthusamy K, Tuft SJ, Liskova P, Davidson AE.", "doi": "10.1016/j.ophtha.2026.10.024", "pmid": "43062380", "url": "https://doi.org/10.1016/j.ophtha.2026.10.024", "tags": [], "abstract": "", "rankSystem": "CAS", "rankEdition": 2025, "rankZone": 1, "finding": "", "why": "", "problem": "", "innovation": "", "limitations": "", "next": "", "reviewStatus": "metadata_only"}, {"id": "doi-10-1016-j-ajo-2026-11-016", "journal": "American Journal of Ophthalmology", "group": "Eye", "sections": ["Eye", "DryEye"], "date": "2026-11-20", "type": "Research Article", "title": "Association of allergic conjunctivitis severity with meibomian gland abnormalities in children: a cross-sectional study.", "zh": "", "authors": "Yan J, Du J, Deng Y, Chen Y, Chen W, Li J.", "doi": "10.1016/j.ajo.2026.11.016", "pmid": "43064053", "url": "https://doi.org/10.1016/j.ajo.2026.11.016", "tags": [], "abstract": "Purpose To evaluate associations of allergic conjunctivitis (AC) severity with meibomian gland structure and function and tear film stability in children. Design Single-center, cross-sectional study. Participants The primary analysis included 144 children: 32 healthy controls and 112 patients with active AC classified as mild (n = 42), moderate (n = 39), or severe (n = 31). Supplementary analyses included 141 adults. Methods Participants underwent standardized ocular surface examinations and noncontact meibography. AC severity was classified according to ocular surface signs. Multivariable linear regression evaluated severity-related associations after adjustment for age, sex, and disease duration. Main outcome measures Total meibomian gland loss (MGL), fluorescein breakup time (FBUT), gland morphology scores, and meibum quality and expressibility scores. Results Median total MGL was 9.00%, 20.50%, 31.00%, and 36.00% in the control, mild, moderate, and severe groups, respectively. Corresponding median FBUT values were 9.50, 4.00, 3.00, and 2.00 seconds (both overall P Conclusions Greater AC severity was associated with greater MGL and reduced tear film stability in children. Meibum quality grade, however, did not differ significantly across groups. These findings support including meibomian gland and tear film assessments in the clinical evaluation of pediatric AC. Longitudinal studies are needed to clarify the temporal relationship between AC severity and gland abnormalities.", "rankSystem": "CAS", "rankEdition": 2025, "rankZone": 1, "finding": "", "why": "", "problem": "", "innovation": "", "limitations": "", "next": "", "reviewStatus": "metadata_only"}, {"id": "doi-10-1038-s41467-026-78669-5", "journal": "Nature Communications", "group": "SingleCell", "sections": ["SingleCell"], "date": "2026-11-20", "type": "Research Article", "title": "velotest: statistical assessment of RNA velocity embeddings reveals quality differences for reliable trajectory visualizations.", "zh": "", "authors": "Bischoff S, Poličar PG, Mukherjee S, Macke JH, Claassen M, Schröder C.", "doi": "10.1038/s41467-026-78669-5", "pmid": "43064728", "url": "https://doi.org/10.1038/s41467-026-78669-5", "tags": [], "abstract": "Contemporary single-cell RNA-sequencing studies typically use RNA velocity analyses to investigate cellular dynamics. Commonly, RNA velocities are assessed with two-dimensional projections. Although it is well established that nonlinear embeddings of gene expression data cannot comprehensively preserve the structure of the original high-dimensional data across scales, there is no tool that systematically assesses and quantifies the faithfulness of velocity embeddings. This situation potentially leads to misleading velocity visualizations and putative cell state transitions. To this end, we introduce velotest, a cell-level statistical test that quantifies the faithfulness of a velocity embedding with respect to its high-dimensional counterpart. Applying velotest across multiple datasets and embedding methods, we find strong differences in the embedding qualities between embedding methods, datasets, and regions in individual datasets. velotest thus provides an essential validation step and enables researchers to select a suitable visualization of high-dimensional velocities, ensuring that hypotheses drawn from velocity projections are grounded in accurately represented dynamics.", "rankSystem": "CAS", "rankEdition": 2025, "rankZone": 1, "finding": "", "why": "", "problem": "", "innovation": "", "limitations": "", "next": "", "reviewStatus": "metadata_only"}, {"id": "doi-10-1126-sciadv-aee4872", "journal": "Science Advances", "group": "SingleCell", "sections": ["SingleCell"], "date": "2026-11-20", "type": "Research Article", "title": "Subclonal evolution can shape the transition toward a sarcomatoid phenotype in pleural mesothelioma.", "zh": "", "authors": "Arnould M, Assie JB, Meiller C, Sequeiros R, Imbeaud S, Roehrig A, Boano C, Le Corre D, Mouillet-Richard S, Poupel L, Lavergne J, Hofman V, Hofman P, Humez S, Scherpereel A, Le Pimpec-Barthes F, Zucman-Rossi J, Blanquart C, Jaurand MC, Lantuejoul S, Hirsch TZ, Damotte D, Jean D.", "doi": "10.1126/sciadv.aee4872", "pmid": "43063279", "url": "https://doi.org/10.1126/sciadv.aee4872", "tags": [], "abstract": "A better understanding of intratumor heterogeneity in pleural mesothelioma (PM) is crucial to implementing precision medicine for this deadly cancer. Using single-cell RNA sequencing approaches on tumor samples and derived primary cell lines, we defined four phenotypic cell types, related to overall survival in larger bulk cohorts: epithelioid, sarcomatoid, intermediate, and nondifferentiated. Some tumor samples showed intratumor phenotypic heterogeneity, associated with subclonal evolution, in which sarcomatoid cells can emerge from parental cells with an intermediate phenotype following the acquisition of copy number variations. Subclones were conserved in cell lines and retained their specific phenotypes, suggesting high phenotypic heritability. Spatial transcriptomics illustrated the link between phenotypic and subclonal evolution, showing that subclonal cells were colocalized and exhibited specific morphologies within the tumor tissue. Our study provides a comprehensive single-cell profiling of PM tumor cells and reveals a link between phenotypic evolution, clonal architecture, and tumor spatial organization.", "rankSystem": "CAS", "rankEdition": 2025, "rankZone": 1, "finding": "", "why": "", "problem": "", "innovation": "", "limitations": "", "next": "", "reviewStatus": "metadata_only"}, {"id": "doi-10-1126-sciadv-aed0035", "journal": "Science Advances", "group": "SingleCell", "sections": ["SingleCell"], "date": "2026-11-20", "type": "Research Article", "title": "Immune infiltrate predicts response to αPD1/αCTLA4 but not αPD1 and distinguishes programs of primary resistance in metastatic melanoma.", "zh": "", "authors": "Huang AY, Burke KP, Glettig MC, Porter R, Fatouros P, Li JM, Meiger L, Rosado V, Xu S, Yang J, Robitschek E, Vokes N, Ricker C, Tarantino G, Chen J, Aprati TJ, He Y, Wang C, Fu D, Ho LL, Galani K, Freeman GJ, Buchbinder EI, Hodi FS, Lian CG, Kellis M, Boland GM, Sharpe AH, Liu D.", "doi": "10.1126/sciadv.aed0035", "pmid": "43063269", "url": "https://doi.org/10.1126/sciadv.aed0035", "tags": [], "abstract": "While immune-checkpoint blockade (ICB) has revolutionized treatment of metastatic melanoma, the identification of robust biomarkers to predict the relative efficacy of single versus combination ICB has been challenging. We performed a meta-analysis of eight cohorts of patients treated with anti-PD-1 ( n = 290), anti-CTLA-4 ( n = 175), and combination anti-PD-1/anti-CTLA-4 ( n = 51) with pretreatment tumor sequencing and clinical annotations. Surprisingly, the increased response rate to combination anti-PD-1/anti-CTLA-4 compared to anti-PD-1 monotherapy was observed only in highly immune infiltrated tumors, and not in immune-low tumors. Stratifying tumors by high or low frequency of immune cells also distinguished context-dependent programs of primary resistance to single and combination ICB. Notably, hypoxia-related pathways were enriched in nonresponders to anti-PD-1 ICB in immune-high, but not immune-low, tumors. Using an independent cohort of patients with scRNA-seq data, we observed that correlates of hypoxia were associated with increased stromal tumor receptor-ligand interactions. As proof of concept, selective inhibition of HIF-2α, a component of the hypoxia pathway and highly expressed in endothelial cells and fibroblasts, in combination with anti-PD-1, controlled tumor growth in mouse models of highly immune-infiltrated tumors but not poorly immune-infiltrated tumors. Our work demonstrates how stratification by tumor immune characteristics and clinical features can lead to the rational discovery of novel therapeutic targets.", "rankSystem": "CAS", "rankEdition": 2025, "rankZone": 1, "finding": "", "why": "", "problem": "", "innovation": "", "limitations": "", "next": "", "reviewStatus": "metadata_only"}, {"id": "doi-10-1001-jamaophthalmol-2026-5197", "journal": "JAMA Ophthalmology", "group": "Eye", "sections": ["Eye"], "date": "2026-11-19", "type": "Research Article", "title": "A Macular Mass.", "zh": "", "authors": "Anibire O, Boldt HC, Binkley E.", "doi": "10.1001/jamaophthalmol.2026.5197", "pmid": "43056126", "url": "https://doi.org/10.1001/jamaophthalmol.2026.5197", "tags": [], "abstract": "", "rankSystem": "CAS", "rankEdition": 2025, "rankZone": 1, "finding": "", "why": "", "problem": "", "innovation": "", "limitations": "", "next": "", "reviewStatus": "metadata_only"}, {"id": "doi-10-1001-jamaophthalmol-2026-5250", "journal": "JAMA Ophthalmology", "group": "Eye", "sections": ["Eye"], "date": "2026-11-19", "type": "Research Article", "title": "Low-Concentration Atropine Eye Drops in Children With Myopia and Intermittent Exotropia: The AMIXT2 Randomized Clinical Trial.", "zh": "", "authors": "Wang Z, Zuo X, Tang H, Zhang Y, Li T, Xie Y, Leng Z, Chen X, Wang L, Wang X, Liu H.", "doi": "10.1001/jamaophthalmol.2026.5250", "pmid": "43056108", "url": "https://doi.org/10.1001/jamaophthalmol.2026.5250", "tags": [], "abstract": "Importance The optimal atropine concentration for myopia control in children with coexisting intermittent exotropia (IXT) remains uncertain. Objective To compare the efficacy and safety of 0.01%, 0.02%, and 0.04% atropine eye drops in children with myopia and IXT. Design, setting, and participants This single-center, double-masked, 3-arm randomized clinical trial was conducted from September 2023 to March 2026. Children aged 6 to 12 years with basic-type IXT and myopia (cycloplegic spherical equivalent [SE], -0.50 to -6.00 diopters [D]) were enrolled. Data analysis was conducted from March 2026 to July 2026. Interventions Participants were randomized 1:1:1 to 0.01%, 0.02%, or 0.04% atropine eye drops nightly in both eyes. Main outcomes and measures The primary outcome was 12-month change in cycloplegic SE. Secondary outcomes included changes in axial length (AL), exotropia conditions, binocular vision, and ocular safety parameters. Results Among 264 randomized children (mean [SD] age, 8.4 [1.5] years; 130 female [49.2%]), 224 (84.8%) completed the 12-month assessment. Mean (SD) SE changes were -0.43 (0.50) D, -0.35 (0.51) D, and -0.18 (0.60) D with 0.01%, 0.02%, and 0.04% atropine, respectively (overall P = .001). Compared with 0.01% and 0.02% atropine, 0.04% atropine was associated with less SE progression (vs 0.01%: difference, 0.24 D; 95% CI, 0.11-0.37 D; P Conclusions and relevance In the AMIXT2 randomized clinical trial among children with myopia and IXT, 0.04% atropine eye drops were associated with less myopia progression and axial elongation over 12 months than 0.01% or 0.02% atropine eye drops. Higher concentrations were associated with greater reductions in near magnitude of exodeviation, which warrant further investigation. Trial registration chictr.org.cn Identifier: ChiCTR2300075312.", "rankSystem": "CAS", "rankEdition": 2025, "rankZone": 1, "finding": "", "why": "", "problem": "", "innovation": "", "limitations": "", "next": "", "reviewStatus": "metadata_only"}, {"id": "doi-10-1001-jamaophthalmol-2026-5222", "journal": "JAMA Ophthalmology", "group": "Eye", "sections": ["Eye"], "date": "2026-11-19", "type": "Research Article", "title": "Impression Cytologic Evaluation of Microsporidial Keratoconjunctivitis.", "zh": "", "authors": "Yu H, Zeng J, Zhang B.", "doi": "10.1001/jamaophthalmol.2026.5222", "pmid": "43056122", "url": "https://doi.org/10.1001/jamaophthalmol.2026.5222", "tags": [], "abstract": "", "rankSystem": "CAS", "rankEdition": 2025, "rankZone": 1, "finding": "", "why": "", "problem": "", "innovation": "", "limitations": "", "next": "", "reviewStatus": "metadata_only"}, {"id": "doi-10-1001-jamaophthalmol-2026-5279", "journal": "JAMA Ophthalmology", "group": "Eye", "sections": ["Eye"], "date": "2026-11-19", "type": "Research Article", "title": "Grafting vs Intraoperative Mitomycin C for Preventing Pterygium Recurrence: A Randomized Clinical Trial.", "zh": "", "authors": "Peng WY, Deng WR, Luo L, Jin L, Liu H, Zhu HF, Zhu L, Luo FT, Wang CX, Zhou SY.", "doi": "10.1001/jamaophthalmol.2026.5279", "pmid": "43056092", "url": "https://doi.org/10.1001/jamaophthalmol.2026.5279", "tags": [], "abstract": "Importance Postoperative recurrence remains a major challenge after primary pterygium surgery, and whether grafting approaches are more effective than intraoperative mitomycin C (MMC) in reducing recurrence remains uncertain. Objective To determine whether grafting with conjunctival autograft (CAG) or amniotic membrane transplant (AMT) is superior to MMC in preventing 1-year recurrence after primary pterygium excision. Design, setting, and participants This multicenter, open-label randomized clinical trial with masked outcome assessment with 12-month follow-up was conducted at 5 tertiary hospitals in China. Enrollment and follow-up occurred between January 2016 and December 2020, and data were analyzed from September 2025 through January 2026. Patients aged 18 to 80 years with primary pterygium were enrolled and randomly assigned 1:1:1 to AMT (n = 249), MMC (n = 248), or CAG (n = 253). Interventions Standardized pterygium excision with conjunctival excision extending radially 4 mm from the limbus, combined with AMT, MMC, or CAG. Main outcomes and measures The primary outcome was 12-month postoperative recurrence. Secondary outcomes included best-corrected visual acuity, epithelial healing time, and conjunctival congestion scores. Results Of 750 randomized participants (mean [SD] age, 57.2 [10.5] years; 487 women [64.9%]), 681 (90.8%) completed follow-up. Recurrence in the intention-to-treat analysis was 57 participants of 249 with AMT (22.9%), 34 of 248 with MMC (13.7%), and 13 of 253 with CAG (5.0%). Risk differences were 9.2 percentage points for AMT vs MMC (98.33% CI, 0.6-17.9; P = .01), 17.9 for AMT vs CAG (98.33% CI, 10.5-25.4; P Conclusions and relevance In this randomized clinical trial, among patients undergoing primary pterygium excision, recurrence was lowest with CAG, intermediate with MMC, and highest with AMT. The moderate magnitude of the between-procedure differences makes recurrence prevention an important-but not exclusive-determinant of surgical choice and may inform individualized surgical management. Trial registration ClinicalTrials.gov Identifier: NCT02102776.", "rankSystem": "CAS", "rankEdition": 2025, "rankZone": 1, "finding": "", "why": "", "problem": "", "innovation": "", "limitations": "", "next": "", "reviewStatus": "metadata_only"}, {"id": "doi-10-1016-j-ophtha-2026-10-027", "journal": "Ophthalmology", "group": "Eye", "sections": ["Eye"], "date": "2026-11-19", "type": "Research Article", "title": "Indocyanine Green Angiography of Iris Racemose Hemangioma (Iris Arteriovenous Malformation).", "zh": "", "authors": "de Esteban Maciñeira E, Blanco Teijeiro MJ, Bande Rodríguez MF.", "doi": "10.1016/j.ophtha.2026.10.027", "pmid": "43062382", "url": "https://doi.org/10.1016/j.ophtha.2026.10.027", "tags": [], "abstract": "", "rankSystem": "CAS", "rankEdition": 2025, "rankZone": 1, "finding": "", "why": "", "problem": "", "innovation": "", "limitations": "", "next": "", "reviewStatus": "metadata_only"}, {"id": "doi-10-1016-j-ajo-2026-11-011", "journal": "American Journal of Ophthalmology", "group": "Eye", "sections": ["Eye"], "date": "2026-11-19", "type": "Research Article", "title": "Smoke, Not Smoking, as a Possible Risk Factor Triggering Conversion in Leber's Hereditary Optic Neuropathy: A Retrospective Case Series.", "zh": "", "authors": "Gauthier DA, Golmohammadi M, Elmaseh SA, Liao YJ, Pargalava N, Huang C, Firn KA, Karanjia R, Sadun AA.", "doi": "10.1016/j.ajo.2026.11.011", "pmid": "43057505", "url": "https://doi.org/10.1016/j.ajo.2026.11.011", "tags": [], "abstract": "Objective To describe the association of wildfire smoke exposure with conversion of Leber hereditary optic neuropathy (LHON) mutation carriers to symptomatic LHON. Design In this retrospective observational case series, we performed an exploratory analysis of our institutional LHON registry for patients under observation during 2017-2018. Subjects Four genetically confirmed LHON mutation carriers who developed bilateral vision loss after the 2017 Wine Country, or 2018 Camp Fire (Paradise) wildfire and 40 genetically confirmed carriers were examined and followed up from 2017-2018 to 2026. Methods We described four LHON mutation carriers who developed bilateral vision loss within 4-8 weeks of documented wildfire smoke exposure during the 2017 Wine Country and 2018 Camp (Paradise) fires in Northern California. We performed an exploratory analysis of our institutional LHON registry for patients under observation during 2017-2018. Main outcome measures Time from regional wildfire smoke exposure to symptomatic conversion and conversion frequency among registry carriers. Results All four carriers resided in regions where the Air Quality Index exceeded 150 for multiple consecutive days. Two individuals had remained asymptomatic carriers for more than four decades prior to conversion. In the registry cohort of 40 carriers, 15 converted during 2017-2018. Conversion occurred in 7 of 9 carriers (78%) residing in the Northern California wildfire-affected region, compared with 8 of 31 (26%) residing elsewhere (odds ratio 10.1; Fisher's exact p=0.02). In a time-window analysis restricted to the 8 weeks following the November 2018 Paradise fire, 3 of 5 Northern California carriers at risk (60%) converted compared with 0 of 23 carriers residing outside the region (odds ratio 65.8; Fisher's exact p=0.006). Conclusions We observed temporal clustering of LHON conversion following wildfire smoke exposure and regional enrichment of conversion during 2017-2018. Although causality cannot be established in this retrospective analysis, acute particulate exposure may represent a mitochondrial stressor that lowers the threshold for conversion in susceptible individuals.", "rankSystem": "CAS", "rankEdition": 2025, "rankZone": 1, "finding": "", "why": "", "problem": "", "innovation": "", "limitations": "", "next": "", "reviewStatus": "metadata_only"}, {"id": "doi-10-1016-j-ajo-2026-11-014", "journal": "American Journal of Ophthalmology", "group": "Eye", "sections": ["Eye"], "date": "2026-11-19", "type": "Research Article", "title": "Historical Redlining and Present-Day Vision Disability in Atlanta, Georgia: The Mediating Role of Neighborhood Deprivation.", "zh": "", "authors": "Karne S, Okosun B, Ou X, Price C, O'Banion JJ.", "doi": "10.1016/j.ajo.2026.11.014", "pmid": "43057504", "url": "https://doi.org/10.1016/j.ajo.2026.11.014", "tags": [], "abstract": "Purpose To investigate whether present-day vision disability (VD) prevalence reflects historical redlining in Atlanta, Georgia, quantify mediation by neighborhood deprivation, and assess generalizability across redlined United States (U.S.) cities. Design Ecologic, cross-sectional, retrospective analysis. Subjects 93 Atlanta census tracts and 12,432 tracts across 108 redlined U.S. cities. Methods Census tract-level VD prevalence (2015-2019 American Community Survey) was linked to Home Owners' Loan Corporation (HOLC) grade, Social Deprivation Index (SDI), and distance to nearest eye care office. Unadjusted associations used Spearman correlations and Wilcoxon rank-sum tests. Besag-York-Mollié 2 (BYM2) spatial models estimated risk ratios (RR) per 1-SD adjusting for age and sex; causal mediation analysis quantified the indirect effect of HOLC grade on VD through SDI. Analyses were repeated across 108 cities and pooled via random-effects meta-analysis. Statistical significance was defined as p Main outcome measures VD prevalence by HOLC grade, SDI, racial composition, and eye care distance. Results In Atlanta, HOLC score was not associated with VD risk (fully adjusted RR=0.89, 95% CI: 0.72-1.09). The indirect effect through SDI was significant (ACME=1.15 percentage points per one-grade increase, 95% CI: 0.76-1.56, p Conclusions In Atlanta and across redlined U.S. cities, the association between redlining and VD prevalence was largely explained by neighborhood deprivation. Lack of transportation access was most strongly associated with VD, and eye care offices in Atlanta were not farther from more redlined neighborhoods, suggesting access and affordability may underlie these inequities. Reducing place-based VD inequities may require investing in social determinants, such as transportation, beyond clinical services.", "rankSystem": "CAS", "rankEdition": 2025, "rankZone": 1, "finding": "", "why": "", "problem": "", "innovation": "", "limitations": "", "next": "", "reviewStatus": "metadata_only"}, {"id": "doi-10-1016-j-jtos-2026-11-004", "journal": "The Ocular Surface", "group": "Eye", "sections": ["Eye"], "date": "2026-11-19", "type": "Letter", "title": "Sjögren disease: The essential role of ophthalmologists in timely diagnosis.", "zh": "", "authors": "Akpek EK, Haile M, Church J, Baer AN.", "doi": "10.1016/j.jtos.2026.11.004", "pmid": "43051587", "url": "https://doi.org/10.1016/j.jtos.2026.11.004", "tags": [], "abstract": "", "rankSystem": "CAS", "rankEdition": 2025, "rankZone": 1, "finding": "", "why": "", "problem": "", "innovation": "", "limitations": "", "next": "", "reviewStatus": "metadata_only"}, {"id": "doi-10-1038-s41586-026-11445-z", "journal": "Nature", "group": "Nature", "sections": ["Nature"], "date": "2026-11-19", "type": "Research Article", "title": "Calcium catalysed nucleophilic fluorination.", "zh": "", "authors": "Struijs JJC, Crumpton AE, Gouverneur V, Aldridge S.", "doi": "10.1038/s41586-026-11445-z", "pmid": "43057688", "url": "https://doi.org/10.1038/s41586-026-11445-z", "tags": [], "abstract": "New catalytic manifolds that challenge existing boundaries for synthesis and sustainable manufacturing are notoriously difficult to implement 1 , particularly for catalytic paradigms based on metals which lack access to the fundamental processes that underpin many established d-block mechanistic pathways (e.g. oxidative addition and reductive elimination). The widespread exploitation of systems based on main-group elements therefore requires alternative elementary steps to effect turnover. Herein, we demonstrate a new catalytic platform for nucleophilic fluorination, which exploits a complex based on calcium (the fifth most Earth-abundant element) as the fluoride delivery vehicle. The key intermediate is a calcium-fluoride complex featuring a terminal Ca-F interaction, a unique structural geometry enabled by a highly sterically encumbered dianionic ligand-scaffold. This intermediate links reactants and products through F - capture and release steps, and thereby unlocks catalytic F - shuttling. Late Ca-F bond breaking in the rate-determining fluoride-delivery transition-state means that electronic and steric tuning of F - by calcium is chemically significant; proof-of-concept results show a hitherto unprecedented level of selectivity for substitution over elimination brought about by Ca-modulation. In a broader context, this work demonstrates how control over catalyst speciation and reagent binding affinity are key factors for the future development of sustainable non-transition metal paradigms in catalysis.", "rankSystem": "CAS", "rankEdition": 2025, "rankZone": 1, "finding": "", "why": "", "problem": "", "innovation": "", "limitations": "", "next": "", "reviewStatus": "metadata_only"}, {"id": "doi-10-1016-j-cell-2026-10-047", "journal": "Cell", "group": "Cell", "sections": ["Cell", "SingleCell"], "date": "2026-11-19", "type": "Research Article", "title": "RNA folding drives species-dependent host mRNA partitioning in Ebola virus condensates.", "zh": "", "authors": "Fang J, Lam DC, Mah CK, Watanabe R, Tanner HM, Comi T, Cai Y, Chen CY, Te Velthuis AJW, Brangwynne CP, Yeo GW, Saphire EO.", "doi": "10.1016/j.cell.2026.10.047", "pmid": "43057227", "url": "https://doi.org/10.1016/j.cell.2026.10.047", "tags": [], "abstract": "RNA viruses form membraneless condensates in host cells to drive replication, but whether these compartments regulate host RNAs remains unclear. Using multiplexed error-robust fluorescence in situ hybridization (MERFISH)-based subcellular transcriptomics, we quantified cellular mRNA recruitment into Ebola virus condensates under basal and interferon (IFN)-stimulated states. We find that, in the basal state, cellular RNAs with minimally folded coding regions are selectively recruited. Under IFN stimulation, however, IFN-stimulated genes (ISGs) with structured 3' UTRs concentrate in viral condensates. We find that both RNA structural features are conserved in the viral genome and support its retention in condensates. In parallel, for cellular mRNAs, we find that partitioning into condensates prolongs RNA half-life and amplifies, rather than dampens, ISG expression. Fruit bats, which do not experience severe disease from RNA viruses, instead have ISGs with reduced 3' UTR folding and may evade condensate sequestration, thus enabling balanced antiviral responses. This selective stabilization links condensate function to RNA regulation as a molecular determinant of virus-host co-evolution and disease pathogenesis.", "rankSystem": "CAS", "rankEdition": 2025, "rankZone": 1, "finding": "", "why": "", "problem": "", "innovation": "", "limitations": "", "next": "", "reviewStatus": "metadata_only"}, {"id": "doi-10-1016-j-cell-2026-07-057", "journal": "Cell", "group": "Cell", "sections": ["Cell"], "date": "2026-11-19", "type": "research-article", "title": "Genome writing reveals SVA retrotransposon consequences in X-linked dystonia-parkinsonism.", "zh": "", "authors": "Zhang W, Zhao Y, Prakash P, Appleby H, Barriball K, Capponi S, Jiang Q, Wudzinska AM, Westerdahl JR, Maza AM, Mangiameli K, Vaine CA, Ellis G, Rahman N, Markovic S, Mishkit O, Limberg KC, Maurano MT, Wadghiri YZ, Kim SY, Wheeler VC, Timmers HTM, Bragg DC, Liddelow SA, Brosh R, Boeke JD.", "doi": "10.1016/j.cell.2026.07.057", "pmid": "43057230", "url": "https://doi.org/10.1016/j.cell.2026.07.057", "tags": [], "abstract": "Human retrotransposon insertions are often associated with diseases. Regarding neurodegenerative X-linked dystonia-parkinsonism (XDP), a human-specific SINE-VNTR-Alu (SVA) subfamily F retrotransposon was inserted in intron 32 of the TAF1 gene. Here, we genomically rewrote a portion of the mouse Taf1 allele with the corresponding 78-kb XDP patient-derived TAF1 allele. In mouse embryonic stem cells (mESCs), the presence of the intronic SVA-rather than the hybrid gene structure-reduces hyTAF1 (hybrid TAF1 mRNA) levels. This leads to transcriptional downregulation of genes with TATA boxes enriched in their promoters and triggers apoptosis. Chromatin and transcriptome profiling revealed that intronic SVAs are actively transcribed, forming barriers that likely impede transcription elongation. In mice, neuronal-lineage TAF1 humanization resulted in lethality in male progeny within 2 months. XDP male mice developed severe atrophy centered on the striatum-the same brain region affected in XDP patients. Lastly, CRISPRa-mediated activation of hyTAF1 restored mESC viability, suggesting that boosting TAF1 transcription could be a therapeutic approach.", "rankSystem": "CAS", "rankEdition": 2025, "rankZone": 1, "finding": "", "why": "", "problem": "", "innovation": "", "limitations": "", "next": "", "reviewStatus": "metadata_only"}, {"id": "doi-10-1016-j-cell-2026-10-044", "journal": "Cell", "group": "Cell", "sections": ["Cell"], "date": "2026-11-19", "type": "Research Article", "title": "CD19 CAR T cell therapy alters disease-associated immune signatures in multiple sclerosis.", "zh": "", "authors": "Fischbach F, Pfeffer LK, Engler JB, Neziraj T, Richter J, Sattarnezhad N, Berve K, Lecourt AC, Schlicht F, Konen FF, Sonner JK, Saary P, Willing A, Reinhardt S, Meurs N, Vieira V, Badbaran A, Berger C, Borie D, Seibel J, Fiehler J, Daumer M, Skripuletz T, Kuhle J, Ayuk F, Heesen C, Kröger N, Fehse B, Lanz TV, Pröbstel AK, Friese MA.", "doi": "10.1016/j.cell.2026.10.044", "pmid": "43057228", "url": "https://doi.org/10.1016/j.cell.2026.10.044", "tags": [], "abstract": "Multiple sclerosis (MS) is a chronic inflammatory central nervous system (CNS) disease. Although current immunotherapies control relapses, they have limited impact on progression, which might reflect incomplete access to or modulation of compartmentalized CNS inflammation. Chimeric antigen receptor (CAR) T cells can infiltrate tissues, but their ability to access and eliminate immune cells residing in the CNS remains elusive. We report the treatment of five individuals with progressive or relapsing-remitting MS with autologous CD19 CAR T cells to assess safety-relevant aspects, CNS bioavailability, and compartment-specific effects. The intervention induces remodeling of the cerebrospinal fluid (CSF) B cell pool, with a sustained reduction in CSF humoral biomarkers. Notably, CSF-infiltrating CAR T cells selectively upregulate phosphodiesterase 7B, while reconstituted peripheral B cells show altered cytokine and homing profiles. These findings indicate compartment-specific immunomodulation beyond peripheral B cell depletion and support controlled trials to test safety, durability, and efficacy.", "rankSystem": "CAS", "rankEdition": 2025, "rankZone": 1, "finding": "", "why": "", "problem": "", "innovation": "", "limitations": "", "next": "", "reviewStatus": "metadata_only"}, {"id": "doi-10-1016-j-cell-2026-10-051", "journal": "Cell", "group": "Cell", "sections": ["Cell"], "date": "2026-11-19", "type": "Research Article", "title": "Genomic surveillance reveals age-structured SARS-CoV-2 transmission across settings.", "zh": "", "authors": "Moreno GK, Brock-Fisher T, Krasilnikova LA, Schaffner SF, Burns M, Casiello CE, Messer KS, Petros B, Specht I, DeRuff KC, Siddle KJ, Loreth C, Fitzgerald NA, Rooke HM, Gabriel SB, Smole S, Wohl S, Park DJ, Madoff LC, Brown CM, MacInnis BL, Sabeti PC.", "doi": "10.1016/j.cell.2026.10.051", "pmid": "43057225", "url": "https://doi.org/10.1016/j.cell.2026.10.051", "tags": [], "abstract": "Understanding respiratory virus transmission requires integrating pathogen genomic data with detailed epidemiological context. We analyzed >85,000 SARS-CoV-2 genomes linked to epidemiological data collected in Massachusetts from November 2021 to January 2023. Collected in 666 settings, including schools, colleges, and skilled nursing facilities, this dataset enabled direct comparison of within-setting transmission to community-wide risk. Elevated transmission was concentrated in specific age-defined subpopulations-older adolescents in schools, undergraduates in colleges, and residents in nursing facilities-with little additional risk among other groups, notably including staff. Young adults, particularly in colleges, played a disproportionate role in spread, and new viral lineages consistently expanded first within this group. Viral spread followed reproducible urban-to-rural gradients, and vaccination was associated with reduced onward transmission. We further estimated sequencing thresholds required for timely detection of emerging variants. Together, these findings reveal consistent demographic and spatial structure in SARS-CoV-2 transmission that can inform viral respiratory pathogen genomic surveillance.", "rankSystem": "CAS", "rankEdition": 2025, "rankZone": 1, "finding": "", "why": "", "problem": "", "innovation": "", "limitations": "", "next": "", "reviewStatus": "metadata_only"}, {"id": "doi-10-1016-j-cell-2026-10-046", "journal": "Cell", "group": "Cell", "sections": ["Cell"], "date": "2026-11-19", "type": "Research Article", "title": "Myelin pathology is a key feature of X-linked dystonia-parkinsonism.", "zh": "", "authors": "Prakash P, Limberg KC, Zhang W, Zhao Y, Laborc KF, O'Keeffe A, Appleby H, Vilnaigre BC, O'Dea MR, Fernandez-Cerado C, Legarda GPA, Sy M, Muñoz EL, Ang MAC, Diesta CCE, Han J, Norenberg E, Penney EB, Bragg DC, Mar AC, Brosh R, Boeke JD, Liddelow SA.", "doi": "10.1016/j.cell.2026.10.046", "pmid": "43057229", "url": "https://doi.org/10.1016/j.cell.2026.10.046", "tags": [], "abstract": "X-linked dystonia-parkinsonism (XDP) is an adult-onset movement disorder predominantly affecting males of Filipino descent. It is caused by the insertion of a SINE-variable number of tandem repeat (VNTR)-Alu subfamily F (SVA_F) retrotransposon in the TATA-box binding protein-associated factor 1 (TAF1) gene. A barrier to XDP research has been the lack of animal models. Here, we introduce a conditional humanized XDP mouse model harboring a hybrid mouse-human Taf1/TAF1 gene (hyTAF1) containing the pathogenic SVA_F. We activated hyTAF1 in Nestin + cells and found the resulting XDP male mice recapitulate features of human XDP, including severe motor impairment and striatal atrophy. Transcriptomic, histological, and electron microscopy analyses revealed a reduction in oligodendrocyte-lineage cells and myelin disruption. Consistent with this, postmortem brain tissue from XDP patients revealed similar myelin pathology, including loss of myelin in the medial prefrontal cortex. These results identify oligodendrocyte dysfunction and myelin loss as major contributors to XDP, providing new mechanistic insight into this disorder.", "rankSystem": "CAS", "rankEdition": 2025, "rankZone": 1, "finding": "", "why": "", "problem": "", "innovation": "", "limitations": "", "next": "", "reviewStatus": "metadata_only"}, {"id": "doi-10-1016-j-cell-2026-10-049", "journal": "Cell", "group": "Cell", "sections": ["Cell"], "date": "2026-11-19", "type": "Research Article", "title": "A natural mutation of timeless enhances mosquito thermal adaptation and malaria parasite transmission.", "zh": "", "authors": "Wang G, Sun P, Yang B, Wang Y, Zhou T, Shi Y, Fang G, Li F, Cai W, Huang W, Cui C, Gao H, Ye R, Liu Z, Wang L, Liu J, Zhan S, Wang S.", "doi": "10.1016/j.cell.2026.10.049", "pmid": "43057226", "url": "https://doi.org/10.1016/j.cell.2026.10.049", "tags": [], "abstract": "Anopheles stephensi, a malaria-transmitting mosquito, has invaded Africa and rapidly adapts to the high temperatures in urban settings. However, the molecular basis of its thermal adaptation remains unclear. Here, we identified a variant of a 5-kb deletion in the circadian clock gene timeless (tim -5kb ) that rose to high frequency after 3 years of rearing at high laboratory temperatures. The tim +/ -5kb heterozygous males maintain stable expression of the period gene at high temperatures, conferring a competitive mating advantage through the increased expression of the adipokinetic hormone gene AKH1 to promote energy mobilization and flight activity, together with the upregulation of fatty acyl-CoA reductase genes FAR3 and FAR5 to enhance the production of heptacosane pheromone. Moreover, heterozygous females exhibit increased susceptibility to Plasmodium infection, increasing malaria transmission potential. These findings reveal a circadian-based genetic mechanism that may underlie thermal adaptation in An. stephensi and hold important implications for malaria control in Africa.", "rankSystem": "CAS", "rankEdition": 2025, "rankZone": 1, "finding": "", "why": "", "problem": "", "innovation": "", "limitations": "", "next": "", "reviewStatus": "metadata_only"}, {"id": "doi-10-1126-science-aef8963", "journal": "Science", "group": "Science", "sections": ["Science"], "date": "2026-11-19", "type": "Research Article", "title": "A neural code for generative speech production in human Wernicke's area.", "zh": "", "authors": "Silva AB, Leonard MK, Hullett PW, Levy DF, Wang C, Xu D, Bhaya-Grossman I, Chang EF.", "doi": "10.1126/science.aef8963", "pmid": "43056455", "url": "https://doi.org/10.1126/science.aef8963", "tags": [], "abstract": "Wernicke's area in the posterior temporal lobe is classically defined by its role in speech comprehension, yet a paradox remains: Why does damage here also profoundly impair speech production? Using direct human brain recordings, cortical stimulation, and lesion analysis, we found that this region is not solely for perception. A discrete subzone within Wernicke's area, the left posterior superior temporal gyrus (lpSTG), becomes active before speech, is causally necessary for speech production, and codes features of whole upcoming words rather than low-level acoustics or articulatory information. Its neural activity is distinct from the auditory-feedback responses nearby and can decode intended speech in people with paralysis. Thus, while Wernicke's area is a key part of auditory cortex, it contains a dedicated subregion for speech generation.", "rankSystem": "CAS", "rankEdition": 2025, "rankZone": 1, "finding": "", "why": "", "problem": "", "innovation": "", "limitations": "", "next": "", "reviewStatus": "metadata_only"}, {"id": "doi-10-1126-science-aej3009", "journal": "Science", "group": "Science", "sections": ["Science"], "date": "2026-11-19", "type": "Research Article", "title": "Zero-shot de novo design of a metalloenzyme.", "zh": "", "authors": "El Nesr G, Dürr SL, Mathews II, Wen Q, Zhao K, Sarangi R, Rothlisberger U, Sunden F, Huang PS.", "doi": "10.1126/science.aej3009", "pmid": "43056425", "url": "https://doi.org/10.1126/science.aej3009", "tags": [], "abstract": "De novo design of enzymes is a frontier challenge, requiring consideration of catalytic mechanism and optimization across biochemical and biophysical criteria. Here, we present dEVA (design by EVolutionary Algorithm), a multi-objective protein design method built on principles drawn from evolutionary biology. We apply dEVA to the zero-shot, de novo design of metalloenzymes by optimizing the coordination sphere of catalytic metals. We characterize a bi-zinc metalloenzyme that exhibits promiscuous hydrolytic activity towards both phosphomonoesters and phosphodiesters. This design achieves a rate enhancement ((k cat /K M )/k w ) of up to 3 x 10 13 relative to the uncatalyzed reaction, comparable to characterized natural phosphatases. Structural characterization via x-ray crystallography and absorption spectroscopy supports the design of a de novo active site. These results demonstrate that de novo enzymes can be designed without pre-specified motifs, natural templates, or evolutionary information.", "rankSystem": "CAS", "rankEdition": 2025, "rankZone": 1, "finding": "", "why": "", "problem": "", "innovation": "", "limitations": "", "next": "", "reviewStatus": "metadata_only"}, {"id": "doi-10-1126-science-aeo2218", "journal": "Science", "group": "Science", "sections": ["Science"], "date": "2026-11-19", "type": "Research Article", "title": "In Science Journals.", "zh": "", "authors": "Yeston JS, Smith J, Szuromi P, Lavine MS, Olingy C, Osborne IS, Ferrarelli L, Funk MA, Maroso M, Jiang D, Stajic J.", "doi": "10.1126/science.aeo2218", "pmid": "43056470", "url": "https://doi.org/10.1126/science.aeo2218", "tags": [], "abstract": "Highlights from the Science family of journals.", "rankSystem": "CAS", "rankEdition": 2025, "rankZone": 1, "finding": "", "why": "", "problem": "", "innovation": "", "limitations": "", "next": "", "reviewStatus": "metadata_only"}, {"id": "doi-10-1126-science-aef9553", "journal": "Science", "group": "Science", "sections": ["Science"], "date": "2026-11-19", "type": "Research Article", "title": "Interpenetrating bottlebrush elastomer for low-loss soft ultrasonic interfaces.", "zh": "", "authors": "Wang S, Li R, Tang Z, Li Y, Gong C, Song WJ, Lim CT, Chen X, Zhao X.", "doi": "10.1126/science.aef9553", "pmid": "43056452", "url": "https://doi.org/10.1126/science.aef9553", "tags": [], "abstract": "Ultrasound imaging relies on soft interfaces that transmit sound efficiently between a device and the body. Conventional gel couplants provide low acoustic loss but contain mobile liquid phases that can dry, flow, or leach during extended use. By contrast, mobile phase-free elastomers are more stable but generally attenuate megahertz ultrasound strongly, limiting their use as couplants. We report an interpenetrating bottlebrush elastomer molecularly designed to overcome this trade-off. A densely grafted backbone lowers the shear modulus without increasing shear loss, whereas well-packed sidechains reduce bulk compressibility, jointly suppressing acoustic attenuation in a soft elastomer. The resulting elastomer combines soft tissue-like mechanics with low-loss acoustics, providing a durable couplant for soft ultrasonic interfaces.", "rankSystem": "CAS", "rankEdition": 2025, "rankZone": 1, "finding": "", "why": "", "problem": "", "innovation": "", "limitations": "", "next": "", "reviewStatus": "metadata_only"}, {"id": "doi-10-1126-science-aee8018", "journal": "Science", "group": "Science", "sections": ["Science"], "date": "2026-11-19", "type": "Research Article", "title": "The fate of poised pre-mRNAs shapes mitochondrial activity and cellular differentiation.", "zh": "", "authors": "Rambout X, Nagao R, Gu V, Werner S, Youngyunpipatkul J, Schlierf J, Pröschel C, Maquat LE.", "doi": "10.1126/science.aee8018", "pmid": "43056446", "url": "https://doi.org/10.1126/science.aee8018", "tags": [], "abstract": "Although RNA quality control tightly regulates gene expression, the scope of its regulatory functions in the nucleus remains unclear. In this study, we describe the quality control, on chromatin, of poised intron-containing polyadenylated RNAs (PIA-RNAs). Whether these precursor messenger RNAs (pre-mRNAs) constitute immature mRNAs whose splicing is pending or, alternatively, are degraded by the nuclear RNA exosome depends on whether they engage nuclear cap-binding protein 3 (NCBP3) or anillin, respectively. Many PIA-RNAs inversely controlled by NCBP3 and anillin encode mitochondrial factors. Thus, NCBP3 depletion in mouse as well as pathogenic mutations in the RNA exosome in humans result in reduced mitochondrial activity, muscle weakness, cerebellar hypomyelination, and diminished motor coordination. Our findings reveal a competition between pre-mRNA metabolic pathways whose balance controls mitochondrial function and, when perturbed, leads to neurological diseases.", "rankSystem": "CAS", "rankEdition": 2025, "rankZone": 1, "finding": "", "why": "", "problem": "", "innovation": "", "limitations": "", "next": "", "reviewStatus": "metadata_only"}, {"id": "doi-10-1126-science-aee2641", "journal": "Science", "group": "Science", "sections": ["Science"], "date": "2026-11-19", "type": "Research Article", "title": "Balancing redox-mediated cytotoxicity and catalysis in natural product biosynthesis.", "zh": "", "authors": "Boesger HA, Fang E, Wang R, Harte RJ, Koroleva A, Tunckanat T, Momin AN, Elliott SJ, Metsä-Ketelä M, Newmister SA, Sherman DH.", "doi": "10.1126/science.aee2641", "pmid": "43056466", "url": "https://doi.org/10.1126/science.aee2641", "tags": [], "abstract": "Redox-mediated chemistry is central to both the biosynthesis and cytotoxicity of many natural products, yet how microbes balance these processes remains poorly understood. Here, we uncover a conserved mechanism that coordinates three redox-mediated processes in secondary metabolite biosynthesis: self-protection, prevention of substrate degradation, and late-stage biosynthesis. Using the antitumor antibiotic doxorubicin as a model system, we show that the vicinal oxygen chelate (VOC) protein DnrV prevents reactive oxygen species formation and substrate degradation while promoting P450 catalysis. We expand this paradigm to a conserved family of VOC-fold proteins, redox-associated cytotoxin-binding proteins (REACT), found across bacteria, fungi, and plants. REACT represents a multifunctional protein class that balances antibiotic assembly, self-protection, and prevention of metabolite destruction, providing a foundational understanding of production of redox-active natural products.", "rankSystem": "CAS", "rankEdition": 2025, "rankZone": 1, "finding": "", "why": "", "problem": "", "innovation": "", "limitations": "", "next": "", "reviewStatus": "metadata_only"}, {"id": "doi-10-1126-science-adx5757", "journal": "Science", "group": "Science", "sections": ["Science"], "date": "2026-11-19", "type": "Research Article", "title": "A thalamo-amygdalar circuit drives female vulnerability to chronic pain after early-life stress.", "zh": "", "authors": "Borruto AM, Kohlund T, Rettig L, von Renesse M, Hammer CA, Leonhardt N, Kurpiers B, Calpe-López C, Benn L, Friederich HC, Kuner T, Spanagel R, Wieland S.", "doi": "10.1126/science.adx5757", "pmid": "43056454", "url": "https://doi.org/10.1126/science.adx5757", "tags": [], "abstract": "Childhood adversity increases the risk of chronic pain and anxiety later in life, particularly in women, yet the neural mechanisms linking early-life stress to adult vulnerability remain elusive. Here, we show that social isolation and nerve injury interact to amplify activity-dependent synaptic gain and anticipatory recruitment of the paraventricular thalamus-to-central amygdala pathway in female, but not male, mice. This female-specific circuit sensitization enhances mechanical hypersensitivity and avoidance behaviors in adulthood. Chemogenetic pathway inhibition selectively rescued these behaviors when stress and injury co-occurred, whereas sustained and phasic pathway activation triggered mechanical hypersensitivity and avoidance, respectively. Together, these findings uncovered a latent thalamo-amygdalar synaptic gain state that is unmasked by a subsequent injury and transforms early-life stress into female-specific vulnerability to chronic pain and anxiety-like avoidance.", "rankSystem": "CAS", "rankEdition": 2025, "rankZone": 1, "finding": "", "why": "", "problem": "", "innovation": "", "limitations": "", "next": "", "reviewStatus": "metadata_only"}, {"id": "doi-10-1126-science-aeg4265", "journal": "Science", "group": "Science", "sections": ["Science"], "date": "2026-11-19", "type": "Research Article", "title": "Atmospheric organic nitrogen is a major nutrient source to global oceans.", "zh": "", "authors": "Yu X, Li Y, Shi G, Yu L, Wang Y, Lai S, Zhou Y, Zhang Y, Sun N, Zhang B, Hu Y, Li Z, Jiang Y, Li W, Fu TM, Yu JZ.", "doi": "10.1126/science.aeg4265", "pmid": "43056448", "url": "https://doi.org/10.1126/science.aeg4265", "tags": [], "abstract": "Atmospheric nitrogen (N) deposition is a critical nutrient source for marine ecosystems, but its organic nitrogen (ON) component remains poorly quantified. We measured ON in marine aerosols collected during 21 research cruises transecting multiple ocean basins and both hemispheric high latitudes. We used these observations to constrain and evaluate an atmospheric chemistry model with updated ON sources and sinks, enabling global mapping of ON deposition. The model estimated annual ON deposition to oceans at 12.8 (4.0 to 22.7) teragrams of nitrogen per year (Tg N year -1 ), contributing 27% (11 to 40%) of total N deposition. Marine emissions supply 3.9 (0.7 to 6.9) Tg N year -1 (30%) of deposited ON, while terrestrial sources contribute 8.9 (3.3 to 15.7) Tg N year -1 (70%). In N-limited regions such as the central Atlantic and Indonesian seas, ON accounts for ~50% of total N deposition.", "rankSystem": "CAS", "rankEdition": 2025, "rankZone": 1, "finding": "", "why": "", "problem": "", "innovation": "", "limitations": "", "next": "", "reviewStatus": "metadata_only"}, {"id": "doi-10-1126-science-aeh3114", "journal": "Science", "group": "Science", "sections": ["Science"], "date": "2026-11-19", "type": "Research Article", "title": "Elastic-field reorganization stabilizes soft-lattice perovskites for durable solar cells.", "zh": "", "authors": "Li B, Zhang T, Wang X, Wen Y, Wang Y, Yu X, Yang D.", "doi": "10.1126/science.aeh3114", "pmid": "43056442", "url": "https://doi.org/10.1126/science.aeh3114", "tags": [], "abstract": "The soft lattice that enables the exceptional performance of halide perovskites inherently compromises their operational stability. Here, we show that soft-lattice perovskites can be stabilized through elastic-field reorganization induced by rigid nanodiamond inclusions. Their inclusion enabled efficient bulk-to-boundary load transfer, redistributing and dissipating internal elastic fields at grain boundaries rather than allowing their accumulation within the crystal interior. Suppression of intergranular sliding constrained lattice deformation and mitigated defect generation during prolonged operation. Devices based on the stabilized perovskites with an area of 0.09 square centimeters achieved a certified power conversion efficiency of 27.6%, and minimodules with an area of 16.1 square centimeters achieved 24.3%. These devices retained 80% of their initial PCE after 5000 hours of maximum power point operation at 85°C and 98% after 5000 hours of dynamically varying light-intensity day-night cycling.", "rankSystem": "CAS", "rankEdition": 2025, "rankZone": 1, "finding": "", "why": "", "problem": "", "innovation": "", "limitations": "", "next": "", "reviewStatus": "metadata_only"}, {"id": "doi-10-1126-science-aei2041", "journal": "Science", "group": "Science", "sections": ["Science"], "date": "2026-11-19", "type": "Research Article", "title": "Quaternary carbon-guided carbocation cascade rearrangement to enantioenriched polycycles.", "zh": "", "authors": "Hu XD, Zheng YQ, Zhai K, Li TY, Guo ZX, Li JL, Liu WB.", "doi": "10.1126/science.aei2041", "pmid": "43056424", "url": "https://doi.org/10.1126/science.aei2041", "tags": [], "abstract": "Polycyclic frameworks are prevalent in natural products and bioactive molecules, yet their efficient enantioselective synthesis remains a longstanding challenge. Carbocation cascade cyclization is a textbook reaction that has transformed the synthesis of fused polycycles, but extending this strategy to bridged architectures requires precise control over highly reactive carbocation intermediates while overcoming the intrinsic energetic barrier of transannular cyclization. Herein, we report a quaternary-carbon-guided carbocation cascade rearrangement platform that enables enantioselective and divergent assembly of complex polycyclic architectures from readily available substrates. An enantioenriched quaternary center, installed via transition-metal-catalyzed allylation, serves as a temporary structural linchpin in an acid-triggered cationic cascade rearrangement process, forming multiple bonds and chiral centers in a single step. In combination with pre-embedded quaternary centers, this strategy provides bicyclic and bridged polycyclic frameworks bearing multiple stereocenters with high enantioselectivity.", "rankSystem": "CAS", "rankEdition": 2025, "rankZone": 1, "finding": "", "why": "", "problem": "", "innovation": "", "limitations": "", "next": "", "reviewStatus": "metadata_only"}, {"id": "doi-10-1126-science-aeo2219", "journal": "Science", "group": "Science", "sections": ["Science"], "date": "2026-11-19", "type": "Research Article", "title": "In Other Journals.", "zh": "", "authors": "Vignieri S, Ross SH, Hurtley SM, Funk MA, Jin S, Yeston JS, Hessler A.", "doi": "10.1126/science.aeo2219", "pmid": "43056469", "url": "https://doi.org/10.1126/science.aeo2219", "tags": [], "abstract": "Editors' selections from the current scientific literature.", "rankSystem": "CAS", "rankEdition": 2025, "rankZone": 1, "finding": "", "why": "", "problem": "", "innovation": "", "limitations": "", "next": "", "reviewStatus": "metadata_only"}, {"id": "doi-10-1126-science-aei7840", "journal": "Science", "group": "Science", "sections": ["Science"], "date": "2026-11-19", "type": "Research Article", "title": "Telemetric calorimetry for wireless continuous reaction profiling.", "zh": "", "authors": "Lee S, Weingarten EA, Reynolds MF, Sun K, Cortese AJ, Davies HML, Molnar AC, McEuen PL, Lin S.", "doi": "10.1126/science.aei7840", "pmid": "43056451", "url": "https://doi.org/10.1126/science.aei7840", "tags": [], "abstract": "Real-time monitoring of chemical reactions is often achieved with specialized instrumentation along with custom-designed reactors or intrusive sampling. In this study, we introduce reaction telemetry, a wireless analytical strategy that enables remote, nonintrusive monitoring directly within operating reaction vessels. This approach uses light-powered microelectronic devices that communicate optically and function as autonomous sensing elements. We demonstrate continuous calorimetric measurements across diverse chemical reactions relevant to pharmaceutical and fine chemical synthesis, including photochemical and electrochemical systems, providing access to reaction kinetics under native operating conditions with subsecond temporal resolution. The resulting measurements will support catalyst evaluation, safety assessment, and mechanistic investigation and will accelerate data-driven reaction discovery. By embedding analytical functionality directly within reaction vessels, reaction telemetry establishes a general framework for information-rich observation of chemical processes across research, development, and education.", "rankSystem": "CAS", "rankEdition": 2025, "rankZone": 1, "finding": "", "why": "", "problem": "", "innovation": "", "limitations": "", "next": "", "reviewStatus": "metadata_only"}, {"id": "doi-10-1038-s41592-026-03310-8", "journal": "Nature Methods", "group": "SingleCell", "sections": ["SingleCell"], "date": "2026-11-19", "type": "Research Article", "title": "Space-map: 3D single-cell atlas reconstruction from serial sections.", "zh": "", "authors": "Han R, Ruan C, Zhao B, Tan Y, Monte E, Wei B, Bi J, Karathanos TV, Laquindanum R, Charville GW, Lin Y, Ling N, Ford JM, Nolan GP, Wang M, Zhu C, Snyder MP.", "doi": "10.1038/s41592-026-03310-8", "pmid": "43058204", "url": "https://doi.org/10.1038/s41592-026-03310-8", "tags": [], "abstract": "High-resolution three-dimensional (3D) tissue atlases promise to link cellular architecture to tissue function, but assembling them from serial sections containing millions of cells remains challenging. Here we present Space-map, an accurate and efficient method for reconstructing 3D tissue models from high-content spatial molecular profiles. Space-map combines multiscale feature matching with large deformation diffeomorphic metric mapping to automate global alignment across serial sections while preserving local microanatomy. We generate spatial transcriptomics (Xenium; ~2.7 million cells) and proteomics (CODEX; ~4.8 million cells) datasets from serial sections to build 3D models of a colon polyp and healthy intestinal tissues. These models reveal cell-type heterogeneity in the polyp and preserved crypt and glandular architecture and mucosal-cavity continuity in healthy intestines. Benchmarking on our own and publicly available datasets demonstrates that Space-map achieves substantially higher registration accuracy and up to a tenfold speedup over existing methods, supporting its use as a robust framework for constructing 3D human tissue atlases at single-cell resolution.", "rankSystem": "CAS", "rankEdition": 2025, "rankZone": 1, "finding": "", "why": "", "problem": "", "innovation": "", "limitations": "", "next": "", "reviewStatus": "metadata_only"}, {"id": "doi-10-1016-j-ophtha-2026-10-019", "journal": "Ophthalmology", "group": "Eye", "sections": ["Eye"], "date": "2026-11-18", "type": "Research Article", "title": "Conjunctival Inclusion Cyst after Manual Small-Incision Cataract Surgery.", "zh": "", "authors": "Barwar G.", "doi": "10.1016/j.ophtha.2026.10.019", "pmid": "43049711", "url": "https://doi.org/10.1016/j.ophtha.2026.10.019", "tags": [], "abstract": "", "rankSystem": "CAS", "rankEdition": 2025, "rankZone": 1, "finding": "", "why": "", "problem": "", "innovation": "", "limitations": "", "next": "", "reviewStatus": "metadata_only"}, {"id": "doi-10-1016-j-ophtha-2026-11-023", "journal": "Ophthalmology", "group": "Eye", "sections": ["Eye"], "date": "2026-11-18", "type": "Research Article", "title": "Trends and Variation in Uveal Melanoma Management in the National Cancer Database, 2004-2023.", "zh": "", "authors": "Lee M, So JY, Pershing SY, Afshar AR.", "doi": "10.1016/j.ophtha.2026.11.023", "pmid": "43051324", "url": "https://doi.org/10.1016/j.ophtha.2026.11.023", "tags": [], "abstract": "We evaluated presentation and management of uveal melanoma in the National Cancer Database (NCDB) from 2004-2023 with multivariable logistic regression. Enucleations decreased and globe-sparing radiation increased. Significant socioeconomic and geographic variation in treatment persisted.", "rankSystem": "CAS", "rankEdition": 2025, "rankZone": 1, "finding": "", "why": "", "problem": "", "innovation": "", "limitations": "", "next": "", "reviewStatus": "metadata_only"}, {"id": "doi-10-1016-j-ajo-2026-11-009", "journal": "American Journal of Ophthalmology", "group": "Eye", "sections": ["Eye"], "date": "2026-11-18", "type": "Research Article", "title": "Developing Static Perimetry Thresholds to Assess Visual Field Loss Severity in Patients with Retinitis Pigmentosa.", "zh": "", "authors": "Zhang Q, Shi L, Patch L, Liao W, Mahto H, Tschetter W, Besirli CG, Ong R, Ogundele A, Everett LA, Yang P, Pennesi ME.", "doi": "10.1016/j.ajo.2026.11.009", "pmid": "43051311", "url": "https://doi.org/10.1016/j.ajo.2026.11.009", "tags": [], "abstract": "Objective To assess the correlation between kinetic and static perimetry measurements in patients with retinitis pigmentosa and to develop thresholds that translate 1) mean retinal sensitivity (MRS) from static perimetry and 2) Visual field (VF) area from kinetic perimetry, into kinetic perimetry-derived VF diameter using the International Council of Ophthalmology (ICO) Visual Standards classification of vision loss severity. Design Retrospective cross-sectional study. Subjects Data were obtained from charts of 100 adults with retinitis pigmentosa who had undergone full-field static and kinetic perimetry within a 30-day interval during routine practice at Casey Eye Institute, Oregon Health & Science University, US. Testing Full-field static and kinetic perimetry using the Octopus 900 perimetry device. Main outcome measures Static perimetry full MRS and kinetic perimetry VF area cut-off values were derived from Receiver Operating Characteristic (ROC) analysis by mapping the ICO kinetic perimetry VF diameter cut-offs to classify patients into vision loss severity groups. Youden Index and Area Under the Curve were used to determine optimal cutoff values that maximized diagnostic performance. Weighted Kappa statistics assessed the level of agreement between the derived severity classifications, and the ICO VF diameter classification standards. Results Among the 100 patients, median age was 48.5 years, disease onset at median 28 years, 52% male, 16% with XLRP. MRS correlated strongly with kinetic VF diameter (Spearman's rho 0.83) and with kinetic VF area (rho 0.81); diameter and area were correlated at rho 0.94. ROC analysis derived MRS (dB) cut-offs for vision loss severity were: ≥7.4=mild, 5.3- 2 ) cutoffs for distinguishing severity levels were ≥5706=mild impairment, 410 - Conclusions Strong correlations between MRS and VF diameter measures support the feasibility of mapping static perimetry to kinetic VF diameter ICO standard to classify vision loss severity. This study addresses a critical gap in interpreting retinitis pigmentosa research findings in visual field loss assessment.", "rankSystem": "CAS", "rankEdition": 2025, "rankZone": 1, "finding": "", "why": "", "problem": "", "innovation": "", "limitations": "", "next": "", "reviewStatus": "metadata_only"}, {"id": "doi-10-1038-s41586-026-11251-7", "journal": "Nature", "group": "Nature", "sections": ["Nature"], "date": "2026-11-18", "type": "Research Article", "title": "A glucose-powered artificial neuroimmune axis for metabolic control.", "zh": "", "authors": "Xiu W, Wang Q, Wan L, Liang Z, Panganiban MR, Li X, He A, Zhang Y, Dong H, Fu Y, Wang L, Liu Y.", "doi": "10.1038/s41586-026-11251-7", "pmid": "43052470", "url": "https://doi.org/10.1038/s41586-026-11251-7", "tags": [], "abstract": "Metabolic disorders such as diabetes mellitus are global health crises driven by metabolic imbalance, chronic inflammation and dysfunction of the neuroimmune axis 1-3 . Electroceuticals targeting the autonomic nervous system have shown anti-inflammatory effects, yet existing systems lack the metabolic interoceptive feedback to fully restore immune-metabolic homeostasis 4-9 . Here we report an artificial neuroimmune axis (NeuroAxis) as a closed-loop immunomodulatory therapy for treating metabolic diseases. Analogous to its biological counterpart, NeuroAxis is solely powered by endogenous glucose, operating without batteries or wireless power transfer. It emulates the vagal reflex through closed-loop neuromodulation with metabolic interoceptive feedback. In a rat model of type 1 diabetes, NeuroAxis promotes the recovery of insulin-producing pancreatic β-cells and reduces inflammatory immune responses; in a rat model of type 2 diabetes, it drives macrophage remodelling and reduces systemic chronic inflammation. In both models, NeuroAxis restores glucose tolerance, improves insulin sensitivity and normalizes glycaemic control, with therapeutic effects persisting after treatment cessation. Our artificial neuroimmune axis promotes substantial advances in treating metabolic disorders and represents a general approach for autonomously regulating interorgan communication, central to homeostasis and pathophysiology.", "rankSystem": "CAS", "rankEdition": 2025, "rankZone": 1, "finding": "", "why": "", "problem": "", "innovation": "", "limitations": "", "next": "", "reviewStatus": "metadata_only"}, {"id": "doi-10-1038-s41586-026-11332-7", "journal": "Nature", "group": "Nature", "sections": ["Nature"], "date": "2026-11-18", "type": "Research Article", "title": "Structural and regulatory evolution across the genus Hordeum.", "zh": "", "authors": "Feng JW, Jiang C, Strejčková B, Szecówka M, Haraldsson EB, Lux T, An C, Bayer M, Bertrand YJK, Chudecká M, Villanueva Corrales S, Čegan R, Fiebig A, Gao G, Haghi R, Himmelbach A, Jin Y, Krak K, Komatsuda T, Mahelka V, Mayer KFX, Melonek J, Pecinka A, Sakuma S, Šimková H, Small I, Spannagl M, Stein N, Toegelová H, Waugh R, Wicker T, Zhang H, Zhu Z, Šafář J, Kopecký D, Blattner FR, Yang P, von Korff M, Mascher M.", "doi": "10.1038/s41586-026-11332-7", "pmid": "43052436", "url": "https://doi.org/10.1038/s41586-026-11332-7", "tags": [], "abstract": "The genus Hordeum comprises cultivated barley and its wild relatives, an evolutionarily, ecologically and agriculturally important group of grasses 1,2 . Here we generated a chromosome-scale comparative genomic resource comprising all recognized diploid Hordeum species together with representative polyploid lineages. Comparative analyses reveal extensive structural variation, including inversions and chromosomal rearrangements that disrupt proximal collinearity and reflect lineage-specific genome remodelling. Single-copy gene phylogenies identify ancient hybridization, segmental exchange and introgression, revealing pervasive reticulate evolution during Hordeum diversification. We uncover widespread horizontal gene transfer from Panicoideae grasses into Hordeum, with many transferred genes showing evidence of transcription and functional integration. Retrotransposon proliferation explains genome size variation and provides insights into polyploid genome evolution. Whole-genome alignments reveal contrasting evolutionary dynamics: whereas coding sequences remain highly conserved, regulatory elements undergo rapid turnover, providing a rich source of regulatory diversity for phenotypic evolution. Case studies of vernalization and glume development demonstrate how natural variation in regulatory and coding sequences contributes to flowering time and floral morphology. This comprehensive pangenomic framework establishes Hordeum as a model for studying genome evolution, structural variation and the genetic basis of adaptive traits, offering new avenues for barley improvement.", "rankSystem": "CAS", "rankEdition": 2025, "rankZone": 1, "finding": "", "why": "", "problem": "", "innovation": "", "limitations": "", "next": "", "reviewStatus": "metadata_only"}, {"id": "doi-10-1038-s41586-026-11292-y", "journal": "Nature", "group": "Nature", "sections": ["Nature"], "date": "2026-11-18", "type": "Research Article", "title": "Host-microbe interactions in engineered immunocompetent human gut tissues.", "zh": "", "authors": "López-Sandoval R, Harter MF, Yu Q, Gaspa-Toneu L, Kaltenbach L, Secchia S, Akkerman N, Filip AM, Aubert J, Vasandani SR, Kromer K, Chauvin D, Krishnarajah S, Calvo-Asensio I, Cubela I, Tsiepa S, Almato-Bellavista M, Munteanu S, Fidelin J, Augustin A, Schori C, Bickle M, Bollen Y, Lutolf MP, Recaldin T, Bumann D, Ginhoux F, Hensel M, Beumer J, Nikolaev M, Gjorevski N, Camp JG.", "doi": "10.1038/s41586-026-11292-y", "pmid": "43052451", "url": "https://doi.org/10.1038/s41586-026-11292-y", "tags": [], "abstract": "As a primary port of pathogen entry, the intestinal mucosa has developed a sophisticated set of defences to ward off infections. Investigating the human-specific intestinal barrier responses to pathogens is limited by the lack of models integrating the necessary architectural complexity with an autologous immune compartment 1 . Here we developed engineered barrier models of the human small intestine and colon combining a multilineage epithelium, mucus layer, accessible microbial compartment and autologous tissue-resident immune cells. These tissues recapitulate morphological and functional properties that are region specific and compare with those of the native organ. We use the model to characterize the human epithelial response to Salmonella enterica subsp. enterica serovar Typhimurium at the single-cell level, uncovering the distinct gene regulatory networks that underpin luminal versus intracellular pathogen presence. Invaded epithelial cells initiate an IL-18 signalling axis that triggers cytotoxic T cell activation, resulting in epithelial shedding and barrier disruption. Overall, this work allows for the modular integration of epithelial, microbial and immune compartments, providing a versatile system for studying human intestinal physiology and pathologies.", "rankSystem": "CAS", "rankEdition": 2025, "rankZone": 1, "finding": "", "why": "", "problem": "", "innovation": "", "limitations": "", "next": "", "reviewStatus": "metadata_only"}, {"id": "doi-10-1038-s41586-026-11325-6", "journal": "Nature", "group": "Nature", "sections": ["Nature"], "date": "2026-11-18", "type": "Research Article", "title": "Global patterns and drivers of bee richness and endemism on islands.", "zh": "", "authors": "Marshall L, Ascher JS, Whittaker RJ, Orr MC, Hughes AC, Schrader J, Weigelt P, Kreft H, Vereecken NJ.", "doi": "10.1038/s41586-026-11325-6", "pmid": "43052449", "url": "https://doi.org/10.1038/s41586-026-11325-6", "tags": [], "abstract": "Islands account for a disproportionate share of global biodiversity 1 , yet insects, including invaluable pollinators such as bees 2 , remain underrepresented in island biogeography research 3 . Here we present a global checklist of island bees, recording 4,147 species across 305 islands. Although islands comprise only about 6% of the Earth's land area, they support around 20% of known global bee diversity, and 42% of insular species are endemic, making up around 8% of all known bee species. Island bee species richness peaks at mid-latitudes (at least in the Northern Hemisphere), mirroring continental trends 4 . Native richness increases with island area and declines with isolation, consistent with patterns in other taxa 5 . The strength of island species-area relationships varies among biomes and is steepest in Mediterranean-type systems, which also support disproportionately high bee richness relative to flowering plant diversity. The number of endemic species is highest on large tropical islands, reflecting extensive in situ diversification. Major centres of bee endemism include Madagascar, Malesia (the Greater Sundas and New Guinea) and the Hawaiian islands, where a single large radiation of Hylaeus (Nesoprosopis) dominates 6 . Among islands that are capable of supporting endemic species, endemism scales strongly with total richness. These findings highlight the need to integrate island bee diversity into global conservation planning and position bees as a model for understanding insect evolution and conservation on islands.", "rankSystem": "CAS", "rankEdition": 2025, "rankZone": 1, "finding": "", "why": "", "problem": "", "innovation": "", "limitations": "", "next": "", "reviewStatus": "metadata_only"}, {"id": "doi-10-1038-s41586-026-11247-3", "journal": "Nature", "group": "Nature", "sections": ["Nature"], "date": "2026-11-18", "type": "Research Article", "title": "Quantum position verification with remote untrusted devices.", "zh": "", "authors": "Kavuri GA, Zhang Y, Gookin AR, Patra S, Bienfang JC, Fu H, Alnawakhtha Y, Reddy DV, Mazurek MD, Abellán C, Amaya W, Mitchell MW, Miller CA, Mirin RP, Stevens MJ, Glancy S, Knill E, Shalm LK.", "doi": "10.1038/s41586-026-11247-3", "pmid": "43052433", "url": "https://doi.org/10.1038/s41586-026-11247-3", "tags": [], "abstract": "Position information underpins many modern technologies, from navigation and timing to authentication and critical infrastructure 1-3 . However, classical methods of proving that information originates from a particular position are vulnerable to spoofing 4-6 . This limitation can be overcome with quantum technologies 7-16 , but current protocols rely on trust in quantum hardware that can be undermined 17,18 , or require quantum computers and bounds on adversarial computation 19 . Nevertheless, there has been considerable interest in experimental demonstrations, and aspects of these protocols have been implemented 20-22 . Here we introduce and experimentally demonstrate the Bell-test quantum position verification protocol for device-independent quantum position verification that guarantees security with only observed correlations from a loophole-free Bell test 23-25 across a quantum network. In the experiment, we implement a version of this device-independent protocol against adversaries who, before each trial, are weakly entangled. Our demonstration achieves a one-dimensional localization 2.47(2) times smaller than the best, necessarily non-remote, classical localization protocol. Compared with classical protocols with identical latencies, the localization volume is 4.53(5) times smaller, representing a certifiable quantum advantage. The general Bell-test protocol is loss-tolerant and secure against adversaries with substantial quantum resources. This work allows digital security to be anchored to physically trusted locations, enabling new position-based authentication protocols for applications such as financial transactions, legal agreements and securing critical infrastructure 26-29 .", "rankSystem": "CAS", "rankEdition": 2025, "rankZone": 1, "finding": "", "why": "", "problem": "", "innovation": "", "limitations": "", "next": "", "reviewStatus": "metadata_only"}, {"id": "doi-10-1038-s41586-026-11294-w", "journal": "Nature", "group": "Nature", "sections": ["Nature"], "date": "2026-11-18", "type": "Research Article", "title": "Quantum resistance paradox of low-dimensional superfluids.", "zh": "", "authors": "Wili S, Huang MZ, Bonaccorsi T, Mühlematter MU, Talebi M, Yudkin Y, Gómez-Salvador A, Marijanovic F, Demler E, Esslinger T.", "doi": "10.1038/s41586-026-11294-w", "pmid": "43052440", "url": "https://doi.org/10.1038/s41586-026-11294-w", "tags": [], "abstract": "Resistance in standard conductors decreases with increasing cross-section. Yet, in low-dimensional superconductors and superfluids, residual resistance arises from topological fluctuations of the order parameter, manifesting as phase slips in one-dimensional (1D) and vortices in two-dimensional (2D) systems. How resistance and dissipation evolve as geometry interpolates between these regimes remains an open question. This evolution is masked in solid-state experiments by disorder, impurities and geometric imperfections 1-3 , and poses theoretical challenges due to competing dissipative processes and pronounced finite-size effects. Here, we use a defect-free unitary Fermi gas in a digitally programmable transport geometry to isolate geometric effects on superfluid dissipation and discover a paradox: in the crossover from one dimension to two dimensions, the resistance reaches a minimum. There, widening a channel increases its resistance. Narrower, quasi-1D channels show dissipation described by Langer-Ambegaokar-McCumber-Halperin theory of phase slips 4 . In this regime, varying the channel width yields the predicted exponential scaling of the activation factor over many orders of magnitude. Wider, quasi-2D channels show dissipation consistent with phase-slip events described by a finite-size vortex model 5 . The minimal dissipation in the dimensional crossover reflects a transition in the dominant dissipative mechanism, with both 1D and 2D events simultaneously suppressed. Our measurements suggest a route to minimizing dissipation in superconducting devices and provide a benchmark for theoretical efforts aimed at describing the dimensional crossover.", "rankSystem": "CAS", "rankEdition": 2025, "rankZone": 1, "finding": "", "why": "", "problem": "", "innovation": "", "limitations": "", "next": "", "reviewStatus": "metadata_only"}, {"id": "doi-10-1038-s41586-026-11295-9", "journal": "Nature", "group": "Nature", "sections": ["Nature"], "date": "2026-11-18", "type": "Research Article", "title": "Evidence for p-wave magnetism in electronic band structure of metallic EuSi.", "zh": "", "authors": "Cheng E, Yang Y, Gao Y, Priessnitz J, Hao Y, Liu J, Lou R, Fedorov A, Yao M, Prots Y, Chen H, Koban R, Shi X, Chan YT, Burkhardt U, Goodge BH, Schnelle W, Hasse V, Ansari J, Lu Z, Bencok P, van der Laan G, Hashimoto M, Lu D, Osiecki J, Liu Z, Cui S, Sánchez-Barriga J, Rader O, Chen Y, Wang H, Zang J, Noohinejad L, Wu W, Šmejkal L, Liu J, Liu Z, Felser C.", "doi": "10.1038/s41586-026-11295-9", "pmid": "43052432", "url": "https://doi.org/10.1038/s41586-026-11295-9", "tags": [], "abstract": "One active frontier of quantum-matter research is the realization of p-wave symmetry-breaking phases in fermionic systems, long exemplified by the A phase of superfluid helium-3 (refs. 1-3 ). Achieving p-wave superconductivity 4 and its magnetic analogue 5 -characterized by a time-reversal-symmetric, p-wave spin-polarized Fermi surface-remains a grand challenge 6,7 . Despite recent progress in identifying candidate p-wave magnets 5,7-10 , spin-resolved spectroscopic evidence for their electronic structures remains limited. Here we report angle-resolved photoemission spectroscopy (ARPES) and spin-ARPES evidence for p-wave magnetism in the near-Fermi-level electronic structure of stoichiometric metallic EuSi, supported by symmetry analysis, first-principles calculations and neutron scattering. Neutron diffraction reveals a chiral spiral phase between 33.4 K and 62 K that fulfils archetypal p-wave magnetism criteria: it preserves the combined symmetry of time reversal and lattice translation, while breaking inversion symmetry. Spin-integrated ARPES reveals a pronounced magnetism-driven reconstruction of the electronic structure, with energy separations exceeding 100 meV, and spin-ARPES resolves S y polarization in near-Fermi-level spectral features. The extracted S y exhibits a sign-changing modulation across successive magnetic Brillouin zones and is suppressed near the nodal regions, consistent with the predicted p-wave spin texture and unfolded spin-polarization calculations. Magnetic force microscopy and micro-ARPES further reveal approximately 10-μm chiral magnetic domains. These results identify EuSi as a stoichiometric metallic platform for investigating p-wave magnetism in electronic band structures and spin-symmetry-based functionalities in spintronics 10 , topological matter 7 , superconductivity 11 and beyond.", "rankSystem": "CAS", "rankEdition": 2025, "rankZone": 1, "finding": "", "why": "", "problem": "", "innovation": "", "limitations": "", "next": "", "reviewStatus": "metadata_only"}, {"id": "doi-10-1038-s41586-026-11330-9", "journal": "Nature", "group": "Nature", "sections": ["Nature"], "date": "2026-11-18", "type": "Research Article", "title": "Designing dislocation-driven polar vortex networks in twisted perovskites.", "zh": "", "authors": "Sandholt W, Gauquelin N, Mangeri J, Annys A, Hansen JM, Insinga AR, Dollekamp E, Vitaliti N, Panchal G, Chennit T, De Backer A, Kepaptsoglou D, Mandal R, Rodrigues DR, Van Aert S, Nguyen H, Wurster KI, Bhowmik A, Castelli IE, Simonsen SB, Jespersen TS, Ramasse QM, James RD, Jalan B, Verbeeck J, Lastra JMG, Pryds N.", "doi": "10.1038/s41586-026-11330-9", "pmid": "43052434", "url": "https://doi.org/10.1038/s41586-026-11330-9", "tags": [], "abstract": "Twisting two atomic layers produces a geometric moiré pattern but bonding-induced interfacial reconstruction fundamentally transforms this into an ordered dislocation network-a distinction obscured in weakly bonded van der Waals systems. Although in-plane topological vortex nanostructures arising from twisting-induced lateral strain modulation have been linked to periodic moiré patterns in freestanding perovskite layers 1-3 and 2D bilayers 4 , their coupling to the interfacial dislocation network in twisted layers remains unresolved. Here we demonstrate that twisted freestanding SrTiO 3 (STO) layers undergo interfacial reconstruction into a network of screw dislocations, accompanied by the emergence of in-plane topological vortices. Unlike in previous reports, these vortices are associated with the dislocation network rather than with geometric moiré patterns. Four-dimensional scanning transmission electron microscopy (4DSTEM) reveals a beam deflection texture in registry with the interfacial dislocation network. A machine learning interatomic potential, trained on first-principles calculations, together with phase-field modelling, confirms that competing strains within the dislocation network stabilize polar vortex-antivortex pairs; first-principles calculations further reveal the emergence of an electronic superlattice with a well-defined periodicity. Our results establish twist-controlled dislocation networks as a new and versatile route to designing local polar and electronic structures in oxide materials.", "rankSystem": "CAS", "rankEdition": 2025, "rankZone": 1, "finding": "", "why": "", "problem": "", "innovation": "", "limitations": "", "next": "", "reviewStatus": "metadata_only"}, {"id": "doi-10-1038-s41586-026-11284-y", "journal": "Nature", "group": "Nature", "sections": ["Nature"], "date": "2026-11-18", "type": "Research Article", "title": "Widespread deciduousness reveals diverse Amazonian phenological strategies.", "zh": "", "authors": "Song G, Hughes AC, Lian X, Zeng X, Saleska SR, Huete A, Albert LP, Xu X, Peñuelas J, Zohner CM, Detto M, Wright SJ, Nelson BW, Chen S, Guo Z, Malhi Y, Li X, Lin Z, Su Y, Xiao J, Zhao Y, Zhu P, Liu L, Wu J.", "doi": "10.1038/s41586-026-11284-y", "pmid": "43052430", "url": "https://doi.org/10.1038/s41586-026-11284-y", "tags": [], "abstract": "The Amazon rainforest is a cornerstone of regional and global carbon cycling 1 and is widely regarded and modelled as a perennially evergreen ecosystem 2,3 . This prevailing view, however, masks substantial fine-scale variation in leaf phenology, limiting our capacity to predict ecosystem responses to climate change. Here by combining 10-m Sentinel-2 observations with machine learning, we uncover pervasive, spatially structured seasonal deciduousness across the basin. In 70.0% of the Amazon, leaf shedding precedes leaf flushing by at least 3 months, creating pronounced asynchrony between deciduousness and greenness seasonality, whereas the remainder shows near-synchronous phenology. Hydroclimate emerges as the dominant factor associated with this asynchrony across 51.6% of the area, followed by soil properties (33.2%) and light availability (15.2%). Motivated by this widespread decoupling between deciduousness and canopy greenness, we incorporated deciduousness-constrained leaf turnover and the resulting leaf-age demography into ecophysiological models, yielding spatially widespread improvements in the seasonal agreement between simulated gross primary productivity and satellite-derived photosynthetic seasonality across 79.9% of the basin. These findings challenge the conventional view of Amazonian phenology, demonstrating that previously overlooked deciduousness influences Amazonian carbon dynamics. Incorporating these insights into process-based models is essential for refining projections of climate-forest feedbacks in the Amazon and for understanding its ecological functions under accelerating global change.", "rankSystem": "CAS", "rankEdition": 2025, "rankZone": 1, "finding": "", "why": "", "problem": "", "innovation": "", "limitations": "", "next": "", "reviewStatus": "metadata_only"}, {"id": "doi-10-1038-s41586-026-11270-4", "journal": "Nature", "group": "Nature", "sections": ["Nature", "SingleCell"], "date": "2026-11-18", "type": "Research Article", "title": "Conservation of the tumour microenvironment across organs and species.", "zh": "", "authors": "Januszyk M, Lu JM, Korah M, Jing SL, Xie PY, Fallah M, Pham B, Guo JL, Berry CE, Wang HH, Talbott HE, Nee K, Le T, Garcia CA, Gonçalves A, Nosrati F, Bauer-Rowe KE, Guo C, Agolia JP, Reveron-Thornton RY, Liang NE, Tomasso A, Kameni LE, DiIorio SE, Parker JBL, Morgan AG, Griffin M, Longacre TA, Foster DS, Wan DC, Norton JA, Delitto D, Longaker MT.", "doi": "10.1038/s41586-026-11270-4", "pmid": "43052431", "url": "https://doi.org/10.1038/s41586-026-11270-4", "tags": [], "abstract": "Current understanding of the host tissue response to solid tumours is largely based on investigations of tumour types in isolation 1 . Given the breadth and diversity of human tumour pathology and contributions of tumour microenvironment (TME) cells to disease progression, pan-cancer analysis is needed to bridge major themes of stromal and immune cell evolution. To date, however, efforts to compare the TME response across cancers have been limited in scope 2,3 . Here we conduct a comprehensive pan-cancer analysis by algorithmically screening thousands of publicly available single-cell transcriptomic datasets for stromal and immune signatures across species and tissue types. We demonstrate conserved hallmarks of host cell transcriptional programming in response to malignancy across 42 cancer types in more than 2,000 human and mouse tumour samples. These findings are codified as an interactive web atlas ( tmeatlas.stanford.edu ) and software package (scTME) that will serve as practical resources for the systematic interrogation of the TME in tumours.", "rankSystem": "CAS", "rankEdition": 2025, "rankZone": 1, "finding": "", "why": "", "problem": "", "innovation": "", "limitations": "", "next": "", "reviewStatus": "metadata_only"}, {"id": "doi-10-1038-s41586-026-11254-4", "journal": "Nature", "group": "Nature", "sections": ["Nature"], "date": "2026-11-18", "type": "Research Article", "title": "Flat-band-induced integer doping and phase transition in monolayer graphene.", "zh": "", "authors": "Wang Z, Moulsdale C, Guo X, Liu J, Qiu Z, Soltero I, Jiang Z, Holwill M, Wu J, Sun H, Chai Z, Jones AJH, Zhu M, Yin J, Wong CPY, Taniguchi T, Watanabe K, Goh KEJ, Morozov SV, Mishchenko A, Ulstrup S, Lin L, MacDonald AH, Yu G, Katsnelson MI, Lu J, Fal'ko VI, Geim AK, Huang P, Woods CR, Novoselov KS.", "doi": "10.1038/s41586-026-11254-4", "pmid": "43052450", "url": "https://doi.org/10.1038/s41586-026-11254-4", "tags": [], "abstract": "van der Waals heterostructures are stabilized by a delicate balance between van der Waals, elastic and Coulomb energies 1-4 . Because the interfaces are not covalently bonded, the constituent crystals can slide, rotate and reconstruct, resulting in several possible competing structural phases 2,5,6 . However, controlled tuning of this balance, and hence dynamical control over the stacking, has yet to be achieved. Here we report a dynamical heterostructure in which monolayer graphene is doubly aligned to bulk hexagonal boron nitride (hBN) and monolayer hexagonal boron nitride (mhBN) on either side. In such a system, a global structural phase transition, manifested as a change of crystalline symmetry observed by scanning tunnelling microscopy, could be induced by gating, magnetic field or temperature. This structural transition is accompanied by an exotic electronic transition: the doping of graphene switches between discrete levels, corresponding to an exact integer number of electrons or holes per moiré plaquette. We attribute this integer doping to charge trapping in localized, strain-induced pseudo-Landau levels (flat bands in reciprocal space 7-12 ), produced by moiré reconstruction (strongly enhanced by the mhBN). Electrical control of coupled structural and electronic phase transitions provides a route to engineering strain-induced flat bands and strain-Coulomb correlations in van der Waals heterostructures.", "rankSystem": "CAS", "rankEdition": 2025, "rankZone": 1, "finding": "", "why": "", "problem": "", "innovation": "", "limitations": "", "next": "", "reviewStatus": "metadata_only"}, {"id": "doi-10-1126-sciadv-aef4991", "journal": "Science Advances", "group": "SingleCell", "sections": ["SingleCell"], "date": "2026-11-18", "type": "research-article", "title": "Intestinal BMP SMADs impart the mid-villus pattern through a transcription factor cascade mechanism.", "zh": "", "authors": "Logerfo A, Iqbal J, Ofer R, Kandalgaonkar S, Rizly R, He P, Gnanapragasam MA, Rodney M, Vemuri K, Chen L, Matzuk M, Verzi MP.", "doi": "10.1126/sciadv.aef4991", "pmid": "43050518", "url": "https://doi.org/10.1126/sciadv.aef4991", "tags": [], "abstract": "Differentiated cells of the intestinal villus are not a monolith of equivalent cell types, but an exquisitely patterned continuum of transdifferentiated cells with evolving functions. Villus patterning requires BMP signaling; however, the transcriptional regulators downstream of BMP are unclear. We find that SMAD1 and SMAD5 are necessary for middle villus pattern. Spatial transcriptomics reveal a homeotic-like shift in the villus pattern of SMAD1/SMAD5 mutants, with the villus bottom and tip domains expanding at the expense of the middle. Disruption of mid-villus patterning corresponds to decreases in lipid uptake and runted pups in SMAD1/5 mutants. Unexpectedly, SMAD1/5 is not required for regulation of villus tip identity, which is dependent on SMAD4. Epigenomics approaches reveal a mechanism in which SMAD1/5 directly activate some mid-villus genes and control others via a transcription factor hierarchy, including TBX3. An intestine-specific TBX3 mutant phenocopied the SMAD1/5 mutant. These findings contribute mechanistic details to intestinal villus patterning.", "rankSystem": "CAS", "rankEdition": 2025, "rankZone": 1, "finding": "", "why": "", "problem": "", "innovation": "", "limitations": "", "next": "", "reviewStatus": "metadata_only"}, {"id": "doi-10-1016-j-ajo-2026-11-010", "journal": "American Journal of Ophthalmology", "group": "Eye", "sections": ["Eye"], "date": "2026-11-17", "type": "Research Article", "title": "Evaluating the Effectiveness of Telemedicine Questionnaire Visits for Post-Operative Strabismus Patients.", "zh": "", "authors": "Hodson C, Dewan S, Depala K, Donahue S.", "doi": "10.1016/j.ajo.2026.11.010", "pmid": "43044711", "url": "https://doi.org/10.1016/j.ajo.2026.11.010", "tags": [], "abstract": "Purpose To evaluate the effectiveness, patient satisfaction, and estimated travel burden reduction associated with telemedicine post-operative week one (POW1) follow-up after strabismus surgery. Design Retrospective observational case series. Subjects A total of 201 patients (age range, 2-83 years of age) who underwent strabismus surgery at a single tertiary academic center between March 2020 and February 2026 and completed an electronic POW1 questionnaire. Methods Patients selected for telemedicine follow-up completed an electronic questionnaire assessing postoperative well-being, diplopia status, and medication adherence, and uploaded ocular photographs for subsequent clinician review. A subset of patients completed a telephone satisfaction survey assessing usability and overall experience. Main outcome measures Patient-reported postoperative well-being, diplopia status, medication adherence, post-operative complications, patient satisfaction, and estimated travel avoidance. Results Of 201 patients, 183 completed telemedicine follow-up without an in-person POW1 visit. Overall, 98.4% reported feeling well postoperatively, 66.7% reported complete resolution of diplopia, and 90.7% reported adherence to prescribed medications. Common free-text response themes included reassurance with recovery, expected postoperative symptoms, visual concerns, and questions regarding postoperative care. Twenty-eight patients completed a satisfaction survey, demonstrating high ratings for ease of use, comfort with the platform, and willingness to use the process again. All respondents agreed that telemedicine follow-up saved time compared with a traditional in-person visit. Telemedicine follow-up was associated with an estimated potential travel reduction of 46,249 miles (mean, 252.7 miles per patient). No postoperative complications were identified among patients managed exclusively through telemedicine follow-up. Conclusions Telemedicine POW1 follow-up was feasible in selected strabismus patients, with high satisfaction among telephone survey respondents and substantial estimated potential travel avoidance. These findings support further evaluation of telemedicine follow-up as an alternative to routine in-person POW1 visits in appropriately selected patients.", "rankSystem": "CAS", "rankEdition": 2025, "rankZone": 1, "finding": "", "why": "", "problem": "", "innovation": "", "limitations": "", "next": "", "reviewStatus": "metadata_only"}, {"id": "doi-10-1016-j-jtos-2026-11-006", "journal": "The Ocular Surface", "group": "Eye", "sections": ["Eye", "DryEye"], "date": "2026-11-17", "type": "Research Article", "title": "Clinical feasibility of non-contact in vivo conjunctival goblet cell imaging in ocular surface disease: a prospective study.", "zh": "", "authors": "Kim CY, Yun J, Lee J, Lee GH, Yun YI, Kim MK, Kim KH, Yoon CH.", "doi": "10.1016/j.jtos.2026.11.006", "pmid": "43044759", "url": "https://doi.org/10.1016/j.jtos.2026.11.006", "tags": [], "abstract": "Purpose To evaluate the clinical feasibility and safety of a novel non-contact in vivo imaging system for quantifying conjunctival goblet cell density (GCD) and its associations with clinical features of ocular surface disease (OSD). Methods In this prospective clinical trial (NCT06427629), 132 participants were enrolled, including 43 healthy controls and 89 patients with OSD: dry eye disease (DED, n = 40), Sjögren syndrome (SS, n = 27), ocular graft-versus-host disease (GVHD, n = 15), and Stevens-Johnson syndrome (SJS, n = 7). Non-contact in vivo imaging was performed after topical 0.5% moxifloxacin labeling using a high-speed extended depth-of-field fluorescence microscopy with real-time surface tracking. GCD was quantified from the inferior bulbar conjunctiva by semi-automated analysis. Clinical assessments included ocular surface staining, Schirmer I test, tear break-up time, tear matrix metalloproteinase-9 test, and Ocular Surface Disease Index (OSDI). Results GCD was successfully quantified in 124 eyes (93.9%). No serious adverse events occurred; two mild transient events resolved spontaneously. GCD was significantly lower in OSD than in healthy controls (52.8 vs. 125.0 cells/mm 2 ; P 2 in DED, 51.0 in SS, 70.1 in GVHD, and 18.2 in SJS. GCD correlated negatively with corneal and conjunctival fluorescein staining, and OSDI. Conclusions Non-contact in vivo conjunctival GC imaging is feasible and safe. Quantitative GCD assessment shows cross-sectional associations with selected ocular surface parameters. Test-retest repeatability, quantitative validity against a human reference standard, and clinical utility require further prospective evaluation.", "rankSystem": "CAS", "rankEdition": 2025, "rankZone": 1, "finding": "", "why": "", "problem": "", "innovation": "", "limitations": "", "next": "", "reviewStatus": "metadata_only"}, {"id": "doi-10-1016-j-cell-2026-10-038", "journal": "Cell", "group": "Cell", "sections": ["Cell"], "date": "2026-11-17", "type": "Research Article", "title": "Evolutionary repurposing of a pore-forming toxin drives epithelial remodeling during terrestrial adaptation.", "zh": "", "authors": "Siciliani D, Benedicenti O, Posavi M, Omotade T, Amortegui SX, Garcia BJ, Heimroth RD, Dos Santos YS, Stefani C, Gulisija D, Chen J, Vámosi B, Enyedi B, Johnston CA, Salinas I.", "doi": "10.1016/j.cell.2026.10.038", "pmid": "43044582", "url": "https://doi.org/10.1016/j.cell.2026.10.038", "tags": [], "abstract": "The ability of vertebrates to conquer land is attributed to innovations in respiration and locomotion. However, land adaptation profoundly reshaped mucosal surfaces such as the skin, the main interface between hosts and the environment. To adapt to land, African lungfish annually remodel their skin, forming a cocoon. Here, we report the discovery of a small pore-forming toxin in African lungfish, Protop-CrTX-A, with no other vertebrate counterpart that is sufficient to drive epithelial morphogenesis transcriptional programs. In free-swimming lungfish, goblet cells secrete Protop-CrTX-A into the mucus. During estivation, this niche is replaced by a mucin-low/basal epithelial niche, adjacent to a granulocyte immune niche that becomes the predominant source of Protop-CrTX-A in the estivated skin. Protop-CrTX-A acts as a reversible switch for skin remodeling, sufficient to convert African lungfish skin between aquatic and terrestrial states. We propose that innate immunity, through its capacity to remodel tissues, was a key driver of vertebrate water-land transitions.", "rankSystem": "CAS", "rankEdition": 2025, "rankZone": 1, "finding": "", "why": "", "problem": "", "innovation": "", "limitations": "", "next": "", "reviewStatus": "metadata_only"}, {"id": "doi-10-1016-j-cell-2026-10-041", "journal": "Cell", "group": "Cell", "sections": ["Cell"], "date": "2026-11-17", "type": "Research Article", "title": "Paleogenomics illuminates mobility and changing lifeways in Chalcolithic Anatolia.", "zh": "", "authors": "Aydoğan A, Vural KB, Kazancı DD, Sevkar A, Yüncü E, Sağlıcan E, Yorulmaz S, Güler MN, Yaka R, Doğu AK, Sarmusak E, Palmér AI, Yılmaz Y, Boz B, Erdal ÖD, Adiloğlu G, Aktürk Ş, Altınışık NE, Duru G, Hassett B, Yelozer S, Munro N, Tekin H, Itahashi Y, Yoneda M, Takaoğlu T, Özbal R, Gerritsen F, Sarı D, Erdoğu B, Steadman S, McMahon G, Öztan A, Özdoğan M, Özdoğan E, Biehl P, Rosenstock E, Anvari J, Byrnes J, Orton D, Caneva I, Palumbi G, Kartal G, Witonsky D, Lagerholm VK, Vassou D, Serpetsidaki I, Philippidis A, Carter T, Çevik Ö, Atakuman Ç, Arbuckle B, Kılınç GM, Pavlidis P, Osborne J, Novembre J, Götherström A, Nafplioti A, Raghavan M, Koptekin D, Moots HM, Özer F, Erdal YS, Somel M.", "doi": "10.1016/j.cell.2026.10.041", "pmid": "43044583", "url": "https://doi.org/10.1016/j.cell.2026.10.041", "tags": [], "abstract": "Once labeled the \"Dark Ages\" of Anatolian prehistory, the Chalcolithic period (c. 6000-3000 BCE) was characterized by drastically reduced settlement densities compared with the preceding Neolithic and the succeeding Bronze Ages, a change interpreted as population decline. Using 44 new genomes combined with published data, we find no evidence for a population reduction. The genetic evidence instead suggests that populations in Chalcolithic Anatolia were increasingly mobile and/or growing in size while receiving gene flow from eastern regions (e.g., East Anatolia and the South Caucasus) through a 3,000-year-long admixture process. We propose that genetic and archaeological evidence may be reconciled by hypothesizing the presence of communities with dispersed and mobile lifeways that are mostly invisible to archaeology. These communities also practiced consanguinity at frequencies unobserved in previous periods. Finally, we identify a mid-5th-millennium BCE individual in Central Anatolia carrying ∼10%-30% Pontic-Caspian Steppe-related ancestry, shedding light on mobility between the Eurasian Steppe and Anatolia.", "rankSystem": "CAS", "rankEdition": 2025, "rankZone": 1, "finding": "", "why": "", "problem": "", "innovation": "", "limitations": "", "next": "", "reviewStatus": "metadata_only"}, {"id": "doi-10-1038-s41588-026-02843-0", "journal": "Nature Genetics", "group": "SingleCell", "sections": ["SingleCell"], "date": "2026-11-17", "type": "Research Article", "title": "Integrated QTL mapping and CRISPR screening in pooled iPSC-derived microglia reveals genetic drivers of neurodegenerative risk.", "zh": "", "authors": "Perez-Alcantara M, Washer SJ, Chen Y, Steer J, Gonzalez-Padilla D, McWilliam J, Willé D, Panousis N, Kolberg P, Navarro-Guerrero E, Alasoo K, Hall-Roberts H, Williams J, Cowley SA, Trynka G, Bassett AR.", "doi": "10.1038/s41588-026-02843-0", "pmid": "43045849", "url": "https://doi.org/10.1038/s41588-026-02843-0", "tags": [], "abstract": "Mounting evidence implicates microglia in neurodegeneration, but linking disease-associated genetic variants to target genes and cellular phenotypes is hindered by the inaccessibility of these cells. We differentiated 261 human induced pluripotent stem cell lines into microglia-like (iMGL) cells in pools with phenotypic (differentiation, phagocytosis and migration) and single-cell transcriptomic readouts. Burden analysis of deleterious variants detected 36 genes influencing microglial phenotypes. Expression quantitative trait locus (eQTL) analysis identified 7,121 eQTL-associated genes and 79 colocalizations across four neurodegenerative disease genome-wide association studies, half of which had limited prior evidence of causality. Integration of eQTL and phenotypic associations highlighted the role of disease-relevant variants, including LRRK2 and TREM2 acting through microglial phagocytosis. A coupled CRISPR screen identified a role for TREM2 in phagocytosis and highlighted the importance of cell type in the directionality of phenotypic effects. By contextualizing variant effects within iMGLs in different inflammatory states, we provide a comprehensive framework for interpreting the function of risk loci in neurodegenerative disorders.", "rankSystem": "CAS", "rankEdition": 2025, "rankZone": 1, "finding": "", "why": "", "problem": "", "innovation": "", "limitations": "", "next": "", "reviewStatus": "metadata_only"}, {"id": "doi-10-1016-j-ophtha-2026-11-017", "journal": "Ophthalmology", "group": "Eye", "sections": ["Eye"], "date": "2026-11-16", "type": "Research Article", "title": "Imaging After Retinal Artery Occlusion Versus Transient Ischemic Attack.", "zh": "", "authors": "Shah J, Festok M, Serhan H, Razavi P, Konstantinou EK, Mahrous MA, Kovacs KD, Kiss S.", "doi": "10.1016/j.ophtha.2026.11.017", "pmid": "43039085", "url": "https://doi.org/10.1016/j.ophtha.2026.11.017", "tags": [], "abstract": "Among 3695 matched pairs with same-date emergency department contact, retinal artery occlusion was associated with lower brain imaging use (77.3% versus 91.7%) and slightly higher cervical imaging use (81.7% versus 79.2%) than transient ischemic attack.", "rankSystem": "CAS", "rankEdition": 2025, "rankZone": 1, "finding": "", "why": "", "problem": "", "innovation": "", "limitations": "", "next": "", "reviewStatus": "metadata_only"}, {"id": "doi-10-1016-j-ajo-2026-11-008", "journal": "American Journal of Ophthalmology", "group": "Eye", "sections": ["Eye"], "date": "2026-11-16", "type": "Research Article", "title": "Home and Workplace Secondhand Smoke and Retinal Nerve Fiber Layer Thinning in Never-Smokers: A Nationwide Population-Based Study.", "zh": "", "authors": "Cho SD, Park SH, Jeoung JW.", "doi": "10.1016/j.ajo.2026.11.008", "pmid": "43039286", "url": "https://doi.org/10.1016/j.ajo.2026.11.008", "tags": [], "abstract": "Purpose To examine the association of home and workplace secondhand smoke (SHS) exposure with circumpapillary retinal nerve fiber layer (cpRNFL) thickness, macular ganglion cell-inner plexiform layer (GCIPL) thickness, and glaucoma among lifetime never-smokers. Design Cross-sectional, nationwide population-based study. Participants A total of 4,276 lifetime never-smokers (354 with SHS exposure and 3,922 without SHS exposure) from the Korea National Health and Nutrition Examination Survey 2019-2021. Methods Self-reported SHS exposure at home or in the workplace was the primary exposure. cpRNFL and macular GCIPL thicknesses were measured using spectral-domain optical coherence tomography, and glaucoma was centrally adjudicated according to the International Society of Geographical and Epidemiological Ophthalmology criteria. Survey-weighted linear and logistic regression analyses were performed to investigate the associations of SHS exposure with cpRNFL thickness, macular GCIPL thickness, and glaucoma. Trends across the number of exposure settings were also evaluated. Main outcome measures cpRNFL thickness, macular GCIPL thickness, and glaucoma. Results Compared with unexposed never-smokers, SHS-exposed participants were younger (47.0±13.1 vs. 49.0±14.0 years, standardized mean difference [SMD]=-0.144), had a greater intraocular pressure (15.1±2.3 vs. 14.9±2.3 mmHg, SMD=0.106), deeper anterior chamber (2.79±0.32 vs. 2.74±0.32 mm, SMD=0.155), and a thinner global cpRNFL (93.0±9.9 vs. 94.4±9.9 µm, SMD=-0.145), whereas axial length, macular GCIPL thickness, and glaucoma prevalence (4.4% vs. 3.4%, SMD=0.054) did not differ. After full adjustment, SHS exposure was associated with thinner global cpRNFL (β=-1.826, 95% confidence interval [CI]=-3.082 to -0.570, P=0.004), with a significant trend across the number of exposure settings (P for trend=0.003). In sectoral analyses, thinner cpRNFL was observed in the inferior (β=-3.003, P=0.006) and temporal (β=-1.429, P=0.012) sectors, which remained significant after Bonferroni correction. Exposed never-smokers had higher odds of belonging to the thinnest cpRNFL quartile (odds ratio=1.485, 95% CI=1.081 to 2.039, P=0.015). Average macular GCIPL thickness (P=0.617) and glaucoma (P=0.170) were not significantly associated with SHS exposure. Conclusions SHS exposure was associated with cpRNFL thinning in lifetime never-smokers, but not with macular GCIPL thickness or glaucoma. These findings suggest a subclinical structural vulnerability of the cpRNFL to SHS exposure and underscore the public health imperative of reducing SHS exposure to protect ocular neuroaxonal health in never-smokers.", "rankSystem": "CAS", "rankEdition": 2025, "rankZone": 1, "finding": "", "why": "", "problem": "", "innovation": "", "limitations": "", "next": "", "reviewStatus": "metadata_only"}, {"id": "doi-10-1016-j-ajo-2026-11-007", "journal": "American Journal of Ophthalmology", "group": "Eye", "sections": ["Eye"], "date": "2026-11-16", "type": "Research Article", "title": "Illustrations and Insights: The Octagonal Technique for Sutured Silicone Oil Retention in Aphakic Eyes.", "zh": "", "authors": "Li K, Yuan G.", "doi": "10.1016/j.ajo.2026.11.007", "pmid": "43039285", "url": "https://doi.org/10.1016/j.ajo.2026.11.007", "tags": [], "abstract": "", "rankSystem": "CAS", "rankEdition": 2025, "rankZone": 1, "finding": "", "why": "", "problem": "", "innovation": "", "limitations": "", "next": "", "reviewStatus": "metadata_only"}, {"id": "doi-10-1038-s41592-026-03279-4", "journal": "Nature Methods", "group": "SingleCell", "sections": ["SingleCell"], "date": "2026-11-16", "type": "Research Article", "title": "Echidna: a Bayesian framework for integrative inference of copy number alterations impacting phenotypic plasticity.", "zh": "", "authors": "Fan JL, Zhang M, O'Brien W, Myers JD, Chatterjee S, Hoffer-Hawlik K, Beltran-Velez N, Preau A, Arora I, Melms JC, Biermann J, D'Souza E, Tagore S, Olsen T, Li S, Sims PA, Izar B, Azizi E.", "doi": "10.1038/s41592-026-03279-4", "pmid": "43040036", "url": "https://doi.org/10.1038/s41592-026-03279-4", "tags": [], "abstract": "The ability of cells to adapt their behavior in response to genetic or environmental changes is a fundamental biological process that drives cellular diversity in both normal and pathological contexts, including in tumor evolution. Copy number alterations (CNAs), which can include large-scale changes in genomic ploidy, play a key role in creating adaptive advantages in evolving cell populations. However, tracing these populations across experiments and disentangling the role of CNAs from other sources of transcriptional variability remains challenging and expensive. Here we present Echidna, a Bayesian hierarchical model that integrates single-cell RNA sequencing and bulk whole-genome sequencing data to enable robust integrative inference of CNAs, jointly across samples and treatment time points, to better understand the impact of genomic events on cellular phenotype. Applying Echidna to patient tumor specimens, we demonstrate its superior performance in clonal reconstruction and derive insights into therapy resistance mechanisms.", "rankSystem": "CAS", "rankEdition": 2025, "rankZone": 1, "finding": "", "why": "", "problem": "", "innovation": "", "limitations": "", "next": "", "reviewStatus": "metadata_only"}, {"id": "doi-10-1038-s41592-026-03319-z", "journal": "Nature Methods", "group": "SingleCell", "sections": ["SingleCell"], "date": "2026-11-16", "type": "Research Article", "title": "Joint single-cell capture of Cas9 edits and transcriptomes reveals on- and off-target effects on gene expression.", "zh": "", "authors": "Lorenzini MH, Balderson B, Lavalle SN, Sajeev K, Ho AJ, Light M, Usman OH, Kurgan G, McVicker G.", "doi": "10.1038/s41592-026-03319-z", "pmid": "43040035", "url": "https://doi.org/10.1038/s41592-026-03319-z", "tags": [], "abstract": "A longstanding barrier in genome engineering with CRISPR-Cas9 has been the inability to measure editing outcomes and their functional effects at single-cell resolution. Here we present Superb-seq, which captures single-cell edits and transcriptome effects by integrating Cas9 editing, T7 in situ transcription and single-cell RNA sequencing. We performed Superb-seq on 35,000 cells from three cell lines. Using seven guide RNAs to target four chromatin remodeler genes in 10,000 K562 cells, Superb-seq detected 5,761 edited cells, all on-target sites and 36 off-target sites. Superb-seq improved estimation of downstream perturbation effects on gene expression compared to Perturb-seq. We compared Superb-seq to 4 bulk off-target detection methods and identified between 6 and 210 edit sites across 3 benchmarking guides. Nineteen off-target edits were associated with differential gene expression, nine of which were cell type-specific. In summary, Superb-seq illuminates the consequences of Cas9 genome editing by connecting single-cell edits with changes in gene expression.", "rankSystem": "CAS", "rankEdition": 2025, "rankZone": 1, "finding": "", "why": "", "problem": "", "innovation": "", "limitations": "", "next": "", "reviewStatus": "metadata_only"}]};
